'use strict';
const SEED=JSON.parse(document.getElementById('seed').textContent);
const STORAGE='oversite-command-center-burn-v2';
let S=structuredClone(SEED), page='overview', q='', editor=null, toastTimer;
try{const saved=OSLocalMemory.getItem(STORAGE)||OSLocalMemory.getItem('oversite-command-center-preview-v1');if(saved){const parsed=JSON.parse(saved);if(validState(parsed))S=parsed;}}catch(e){}
const ICONS={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',forecast:'M3 20h18 M4 15l5-6 4 3 7-9',ar:'M12 3v12 M7 10l5 5 5-5 M4 16v4h16v-4',ap:'M12 16V4 M7 9l5-5 5 5 M4 16v4h16v-4',expenses:'M3 7h18v13H3z M7 7V4h10v3 M3 12h18 M10 12v3h4v-3',loan:'M3 9l9-6 9 6 M3 10h18 M5 11v7 M10 11v7 M15 11v7 M20 11v7 M2 21h20',folder:'M3 7V5h6l2 3h10v12H3z',history:'M3 12a9 9 0 1 0 3-6 M3 3v5h5 M12 7v5l3 2',warning:'M12 3l10 18H2z M12 9v5 M12 17v1',money:'M3 6h18v12H3z M8 12a4 4 0 1 0 8 0a4 4 0 1 0-8 0 M5 12h1 M18 12h1',check:'M5 12l4 4L20 5',edit:'M15 4l5 5 M3 21l5-1L21 7l-5-5L3 15z',plus:'M12 5v14 M5 12h14',sync:'M3 12a9 9 0 0 1 15-7 M21 3v5h-5 M21 12a9 9 0 0 1-15 7 M3 21v-5h5'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[k]||ICONS.folder}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=v=>`${v<0?'−':''}$${(Math.abs(v)/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const whole=v=>`${v<0?'−':''}$${(Math.abs(v)/100).toLocaleString('en-US',{maximumFractionDigits:0})}`;
const compact=v=>`${v<0?'−':''}$${(Math.abs(v)/100000).toFixed(Math.abs(v)>=10000000?0:1)}k`;
const cents=v=>Math.round(Number(v)*100);
const sum=a=>a.reduce((a,b)=>a+b,0);
const open=x=>Math.max(0,x.amount-x.paid);
const date=s=>new Date(s+'T12:00:00Z');
const iso=d=>d.toISOString().slice(0,10);
const addDays=(s,n)=>{const d=date(s);d.setUTCDate(d.getUTCDate()+n);return iso(d)};
const todayLabel=s=>date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
const longDate=s=>date(s).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric',timeZone:'UTC'});
const days=(a,b)=>Math.round((date(a)-date(b))/86400000);
const statusPill=s=>`<span class="pill ${s==='Approved'?'green':s==='Submitted'?'amber':s==='Disputed'?'red':s==='Paid'?'green':'neutral'}">${esc(s)}</span>`;
function validState(p){return p&&p.schemaVersion===1&&Array.isArray(p.ap)&&Array.isArray(p.ar)&&Array.isArray(p.expenses)&&Number.isInteger(p.bank)&&p.bank>=-10000000000&&p.bank<=10000000000&&/^\d{4}-\d{2}-\d{2}$/.test(p.asOf)&&p.ap.length<=2000&&p.ar.length<=2000&&p.expenses.length<=2000&&[...p.ap,...p.ar].every(x=>typeof x.id==='string'&&Number.isInteger(x.amount)&&x.amount>=0&&Number.isInteger(x.paid)&&x.paid>=0&&x.paid<=x.amount)&&p.expenses.every(x=>typeof x.id==='string'&&Number.isInteger(x.monthly)&&x.monthly>=0)&&p.loan&&Number.isInteger(p.loan.weekly)&&p.loan.weekly>=0;}
function save(text){if(text)S.activity.unshift({at:new Date().toISOString(),text});S.activity=S.activity.slice(0,200);try{OSLocalMemory.setItem(STORAGE,JSON.stringify(S))}catch(e){toast('Browser storage unavailable. Export a backup to keep changes.')}render();}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function totals(){const labor=sum(S.expenses.filter(x=>x.active&&x.group==='Personnel').map(x=>x.monthly)),fixed=sum(S.expenses.filter(x=>x.active&&x.group!=='Personnel').map(x=>x.monthly));return {ar:sum(S.ar.map(open)),approved:sum(S.ar.filter(x=>x.status==='Approved').map(open)),ap:sum(S.ap.map(open)),labor,fixed,monthly:fixed+labor,weekly:Math.round((fixed+labor)*12/52)+S.loan.weekly};}
function byVendor(){const m={};S.ap.forEach(x=>m[x.vendor]=(m[x.vendor]||0)+open(x));return Object.entries(m).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);}
function dailyAllowance(d,total){const dt=date(d),count=new Date(Date.UTC(dt.getUTCFullYear(),dt.getUTCMonth()+1,0)).getUTCDate();return Math.floor(total/count)+(dt.getUTCDate()<=total%count?1:0)}
function planEvents(withTrinity=S.trinity){const end=addDays(S.asOf,S.forecastWeeks*7-1),events=[];const push=(date,kind,name,inflow,outflow,source='Assumed')=>{if(date>=S.asOf&&date<=end)events.push({date,kind,name,inflow:inflow||0,outflow:outflow||0,source})};
 S.ar.forEach(x=>{if(!open(x)||!x.expected||x.status==='Paid')return;if(x.status!=='Approved'&&!(x.status==='Submitted'&&S.pending)&&!(x.status==='Disputed'&&S.disputed))return;const d=addDays(x.expected,S.extraDelay||0);push(d,'AR',x.customer+' · '+x.invoice,open(x),0,x.status==='Approved'?'Estimated collection':'Conditional collection');});
 S.ap.forEach(x=>{if(open(x)&&x.plan)push(x.plan,'AP',x.vendor+' · '+x.invoice,0,open(x),'Planned; not sent')});
 let loanRemaining=S.loan.remaining;
 for(let d=S.loan.first;d<=end&&d<=S.loan.last;d=addDays(d,7)){if(d<S.asOf)continue;const n=Math.min(S.loan.weekly,loanRemaining);if(n<=0)break;push(d,'Financing','Financing weekly ACH',0,n,'Scheduled');loanRemaining-=n;}
 S.oneoffs.forEach(x=>{if(!x.paid)push(x.date,'Tax / other',x.name,0,x.amount,'User-reported obligation')});
 if(withTrinity)push(S.trinityDate,'Scenario','One-time receipt — one-time receipt',S.trinityAmount,0,'Unconfirmed scenario');
 if(S.newBilling){let bill=S.asOf;while(date(bill).getUTCDay()!==5)bill=addDays(bill,1);for(;bill<=end;bill=addDays(bill,7)){push(addDays(bill,S.collectionLag),'New work','Incremental weekly billing collected',S.weeklyBilling,0,'Assumed; '+S.collectionLag+'-day lag');push(addDays(bill,S.fieldCostLag),'New work','Direct costs of incremental weekly work',0,Math.round(S.weeklyBilling*(100-S.margin)/100),'Assumed; excludes existing AP');}}
 const T=totals();for(let d=S.asOf;d<=end;d=addDays(d,1)){if(S.applyOverhead)push(d,'Allowance','Labor + fixed overhead allowance',0,dailyAllowance(d,T.monthly),'Estimated daily reserve, not due date')}
 return events.sort((a,b)=>a.date.localeCompare(b.date)||b.inflow-a.inflow);}
function forecast(trinity=S.trinity){const ev=planEvents(trinity),end=addDays(S.asOf,S.forecastWeeks*7-1);let balance=S.bank,i=0;const rows=[];for(let d=S.asOf;d<=end;d=addDays(d,1)){let income=0,out=0;while(i<ev.length&&ev[i].date===d){income+=ev[i].inflow;out+=ev[i].outflow;i++}balance+=income-out;rows.push({date:d,inflow:income,outflow:out,balance})}const weeks=[];for(let j=0;j<rows.length;j+=7){const rs=rows.slice(j,j+7);weeks.push({date:rs[0].date,end:rs.at(-1).date,inflow:sum(rs.map(x=>x.inflow)),outflow:sum(rs.map(x=>x.outflow)),balance:rs.at(-1).balance})}return {rows,weeks,events:ev,min:Math.min(S.bank,...rows.map(x=>x.balance)),end:balance,breach:rows.find(x=>x.balance<S.reserve)?.date,negative:rows.find(x=>x.balance<0)?.date};}
function title(label,desc,buttons=''){return `<div class="page-title"><div><div class="eyebrow">OverSite financial workspace</div><h1>${label}</h1><p class="sub">${desc}</p></div><div class="actions">${buttons}</div></div>`}
function stat(label,val,foot,ic,negative=false){return `<div class="stat"><div class="stat-top">${label}${icon(ic)}</div><div class="stat-value ${negative?'negative':''}">${whole(val)}</div><div class="stat-foot">${foot}</div></div>`}
function nav(){const items=[['overview','Overview','overview'],['forecast','Cash forecast','forecast'],['ar','Accounts receivable','ar'],['ap','Accounts payable','ap'],['expenses','Labor & expenses','expenses'],['financing','Financing & taxes','loan'],['files','Files & reports','folder'],['review','Needs review','warning'],['history','Activity','history']];document.getElementById('nav').innerHTML=items.map(([k,l,i])=>`<button class="nav-item ${page===k?'active':''}" data-action="navigate" data-page="${k}">${icon(i)}${l}${k==='review'?'<span class="tag">'+S.review.length+'</span>':''}</button>`).join('');document.getElementById('bread-current').textContent=items.find(x=>x[0]===page)?.[1]||'Overview'}
function toggle(k,label,desc=''){return `<div class="switch-row"><div class="switch-text">${label}${desc?`<small>${desc}</small>`:''}</div><label class="toggle"><input aria-label="${esc(label)}" type="checkbox" data-setting="${k}" ${S[k]?'checked':''}><span></span></label></div>`}
function controls(){return `<section class="panel sidepanel"><div class="panel-head"><div><h2>Scenario controls</h2><p class="sub">Explore, don’t commit</p></div>${icon('forecast')}</div><div class="panel-body">${toggle('trinity','Include One-time receipt','One-time '+whole(S.trinityAmount)+' receipt')}
<div class="form-inline"><div class="field"><label for="trin-date">One-time receipt receipt date</label><input id="trin-date" type="date" value="${S.trinityDate}" data-setting="trinityDate"></div><div class="field"><label for="tri-amt">Amount ($)</label><input id="tri-amt" type="number" min="0" step="500" value="${S.trinityAmount/100}" data-setting="trinityAmount"></div></div>
${toggle('pending','Include submitted AR','Still requires approval')}${toggle('disputed','Include Disputed AR','Correction acceptance required')}${toggle('newBilling','Add future weekly billing','Incremental work, not current AR')}
<div class="control"><div class="control-label"><label for="weekly">Future billing / week</label><b>${whole(S.weeklyBilling)}</b></div><input id="weekly" type="range" min="0" max="80000" step="1000" value="${S.weeklyBilling/100}" data-setting="weeklyBilling"></div>
<div class="control"><div class="control-label"><label for="margin">Field gross margin</label><b>${S.margin}%</b></div><input id="margin" type="range" min="10" max="70" step="1" value="${S.margin}" data-setting="margin"></div>
<div class="form-inline"><div class="field"><label for="lag">Collection lag (days)</label><input id="lag" type="number" min="0" max="180" value="${S.collectionLag}" data-setting="collectionLag"></div><div class="field"><label for="delay">Extra AR delay (days)</label><input id="delay" type="number" min="0" max="90" value="${S.extraDelay}" data-setting="extraDelay"></div></div>
<div class="control-note"><b>Billing ≠ cash.</b> ${S.newBilling?'Future-work scenario is on.':'Turn on future weekly billing to apply the billing and margin controls.'} New sales collect only after the lag; existing AR is counted once.</div></div></section>`}
function chartHtml(F){const without=forecast(false),withT=forecast(true),W=900,H=260,L=70,R=20,T=25,B=35,all=[S.bank,S.reserve,...without.rows.map(x=>x.balance),...withT.rows.map(x=>x.balance)];let low=Math.min(0,...all),high=Math.max(...all);if(high===low)high=low+100000;const spread=high-low;low-=spread*.09;high+=spread*.12;const x=i=>L+(W-L-R)*(i/(without.rows.length-1)),y=v=>T+(H-T-B)*(high-v)/(high-low);const line=arr=>arr.map((r,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(r.balance).toFixed(1)).join(' ');let ticks='';for(let i=0;i<5;i++){let v=low+(high-low)*i/4; ticks+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#edf1f3"/><text x="${L-12}" y="${y(v)+4}" text-anchor="end" font-size="10" fill="#96a5ae">${esc(compact(v))}</text>`;}for(let i=0;i<without.rows.length;i+=Math.ceil(without.rows.length/6))ticks+=`<text x="${x(i)}" y="${H-9}" text-anchor="middle" fill="#94a4ae" font-size="10">${todayLabel(without.rows[i].date)}</text>`;
return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Daily cash projection comparing without One-time receipt and with One-time receipt. Negative values identify unfunded cash needs."><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#70b5a6" stop-opacity=".16"/><stop offset="1" stop-color="#70b5a6" stop-opacity=".01"/></linearGradient></defs>${ticks}<path d="${line(withT.rows)} L${x(withT.rows.length-1)} ${y(low)} L${x(0)} ${y(low)} Z" fill="url(#area)"/><line x1="${L}" x2="${W-R}" y1="${y(S.reserve)}" y2="${y(S.reserve)}" stroke="#d9ac64" stroke-dasharray="3 5"/><text x="${W-R}" y="${y(S.reserve)-6}" text-anchor="end" font-size="9" fill="#b39a76">${whole(S.reserve)} reserve</text><path d="${line(without.rows)}" fill="none" stroke="#91a1b0" stroke-width="2" stroke-dasharray="6 5"/><path d="${line(withT.rows)}" fill="none" stroke="#168276" stroke-width="2.5"/>${F.rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.balance)}" r="4" fill="transparent"><title>${todayLabel(r.date)}: ${money(r.balance)}</title></circle>`).join('')}</svg>`}
function chartPanel(F){return `<section class="panel"><div class="panel-head"><div><h2>Cash runway</h2><p class="sub">${S.newBilling?'Includes future work at '+whole(S.weeklyBilling)+'/week':'Existing AR only; no new work assumed'} · ${todayLabel(S.asOf)} – ${todayLabel(F.rows.at(-1).date)}</p></div><div class="segmented"><button data-action="horizon" data-weeks="4" class="${S.forecastWeeks===4?'on':''}">4W</button><button data-action="horizon" data-weeks="8" class="${S.forecastWeeks===8?'on':''}">8W</button><button data-action="horizon" data-weeks="13" class="${S.forecastWeeks===13?'on':''}">13W</button></div></div><div class="chart-key"><span><i class="linekey dashed"></i>Without One-time receipt</span><span><i class="linekey"></i>With One-time receipt</span><span><i class="linekey floor"></i>Operating reserve</span></div><div class="chart">${chartHtml(F)}</div><div class="chart-end"><span>First reserve breach <strong>${F.breach?todayLabel(F.breach):'None modeled'}</strong></span><span>Lowest balance <strong class="${F.min<0?'negative':''}">${money(F.min)}</strong></span></div></section>`}
function folderCards(){return `<div class="folders">${S.folders.map(x=>`<a class="folder-card" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${icon('folder')}<div><b>${esc(x.name)}</b><small>${esc(x.description)}</small></div><span class="arrow">↗</span></a>`).join('')}</div>`}
function overview(){const T=totals(),F=forecast(),thisWeek=F.events.filter(x=>x.date<=addDays(S.asOf,6)&&x.kind!=='Allowance'),scheduled=sum(thisWeek.map(x=>x.outflow)),laborOverhead=sum(F.events.filter(x=>x.date<=addDays(S.asOf,6)&&x.kind==='Allowance').map(x=>x.outflow));
return title('Your financial picture','One place for cash, collections, bills, and what comes next.',`<button class="btn" data-action="bank">${icon('edit')}Update bank</button><button class="btn primary" data-action="navigate" data-page="forecast">Explore forecast →</button>`)+
`<div class="stats">${stat('Starting bank cash',S.bank,'Snapshot · '+todayLabel(S.asOf),'money')}${stat('Accounts receivable',T.ar,whole(T.approved)+' approved · remainder conditional','ar')}${stat('Vendor accounts payable',T.ap,'Includes provisional & unverified balances','ap')}${stat('Weekly operating allowance',T.weekly,'Labor, fixed costs + weekly Financing','expenses')}</div>
<div class="alert">${icon('warning')}<div><b>Timing is the pressure point.</b> ${money(scheduled)} in dated outflows over the next 7 days, plus ${money(laborOverhead)} in modeled operating allowances. ${F.negative?'A funding shortfall first appears '+todayLabel(F.negative)+'.':'No negative cash is modeled in this scenario.'}</div><button class="panel-link tail" data-action="navigate" data-page="forecast">See cash calendar →</button></div>
<div class="grid-main"><div>${chartPanel(F)}<div class="lower-grid"><section class="panel"><div class="panel-head"><div><h2>Next scheduled payments</h2><p class="sub">Planning dates, not bank instructions</p></div><button class="panel-link" data-action="navigate" data-page="ap">All AP →</button></div><div class="table-wrap"><table><thead><tr><th>Payee / item</th><th>Date</th><th class="money">Amount</th></tr></thead><tbody>${F.events.filter(x=>x.outflow&&x.kind!=='Allowance'&&x.kind!=='New work').slice(0,5).map(x=>`<tr><td><strong>${esc(x.name)}</strong><span class="mini">${esc(x.kind)}</span></td><td class="datecell">${todayLabel(x.date)}</td><td class="money">${money(x.outflow)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Where AP is concentrated</h2><p class="sub">${byVendor().length} vendors · latest working balances</p></div></div>${byVendor().slice(0,4).map(([name,n])=>`<div class="vendor-row"><span class="vendor-icon">${esc(name.slice(0,2).toUpperCase())}</span><div class="vendor-middle">${esc(name)}<div class="vendor-bar"><i style="width:${n/T.ap*100}%"></i></div></div><span class="vendor-balance">${whole(n)}</span></div>`).join('')}<div class="panel-body" style="padding-top:12px;padding-bottom:13px"><button class="panel-link" data-action="navigate" data-page="review">Check unresolved balances →</button></div></section></div><div class="section-gap"><div class="panel-head" style="padding:0 0 12px"><h2>Your financial folders</h2><a class="panel-link" target="_blank" rel="noopener noreferrer" href="${esc(S.root)}">Open workspace ↗</a></div>${folderCards()}</div></div>${controls()}</div>`}
function invoiceView(kind){const isAR=kind==='ar',rows=S[kind].filter(x=>`${x.invoice} ${x.customer||x.vendor} ${x.status||x.quality}`.toLowerCase().includes(q.toLowerCase())),total=sum(rows.map(open));return title(isAR?'Accounts receivable':'Accounts payable',isAR?'Approval is not a payout promise. Keep forecast dates separate from payment status.':'Schedule specific invoices. Unscheduled balances still count in AP.',`<button class="btn primary" data-action="new-invoice" data-kind="${kind}">${icon('plus')}Add ${isAR?'invoice':'bill'}</button>`)+`<section class="panel"><div class="toolbar"><input class="search" id="search" value="${esc(q)}" placeholder="Search ${isAR?'customers':'vendors'} or invoices…" aria-label="Search invoices"><span class="sub">${rows.length} entries · USD</span></div><div class="table-wrap"><table class="table-full"><thead><tr><th>${isAR?'Customer':'Vendor'} / invoice</th><th>Invoice date</th><th>Status / basis</th><th>${isAR?'Forecast receipt':'Planned payment'}</th><th class="money">Balance</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.customer||x.vendor)}</strong><span class="mini">${esc(x.invoice)}</span></td><td class="datecell">${x.date?todayLabel(x.date):'Not provided'}</td><td>${isAR?statusPill(open(x)?x.status:'Paid'):`<span class="pill ${x.quality==='Provisional'?'amber':x.quality==='Verify'?'amber':'neutral'}">${esc(open(x)?x.quality:'Paid')}</span>`}${!isAR&&x.due&&open(x)?`<span class="mini">${days(S.asOf,x.due)>0?days(S.asOf,x.due)+' days past due':'Due '+todayLabel(x.due)}</span>`:''}</td><td class="datecell">${x[isAR?'expected':'plan']?todayLabel(x[isAR?'expected':'plan']):'<span class="mini">Unscheduled</span>'}</td><td class="money"><strong>${money(open(x))}</strong></td><td><div class="actions"><button class="btn" data-action="edit-invoice" data-kind="${kind}" data-id="${x.id}">Edit</button>${open(x)?`<button class="btn" data-action="settle" data-kind="${kind}" data-id="${x.id}">${isAR?'Received':'Paid'}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><div class="totalbar"><span>Visible outstanding balance</span><b>${money(total)}</b></div></section><div class="notice">${isAR?'Approved invoices are included in the baseline using editable estimated receipt dates. Submitted and disputed invoices are excluded unless enabled in Scenario controls. Paid amounts reduce the balance; do not add receipts already included in the bank snapshot again.':'Payment dates are intentions only. This preview does not initiate bank transfers. A partial payment reduces only the specified invoice balance. Statement balances need reconciliation. No assumed vendor agreement has been made.'}</div>`}
function forecastView(){const F=forecast(),T=totals(),no=forecast(false),yes=forecast(true);return title('Cash forecast','A dated cash model, not a same-day revenue assumption.',`<button class="btn" data-action="bank">Edit cash & reserve</button><button class="btn" data-action="csv">Export forecast CSV ↓</button>`)+`<div class="metrics-row"><div class="metric"><label>Ending balance · without One-time receipt</label><b class="${no.end<0?'negative':'positive'}">${money(no.end)}</b></div><div class="metric"><label>Ending balance · with One-time receipt</label><b class="${yes.end<0?'negative':'positive'}">${money(yes.end)}</b></div><div class="metric"><label>Unscheduled vendor balances (excluded from cash forecast)</label><b>${whole(sum(S.ap.filter(x=>!x.plan).map(open)))}</b></div></div><div class="grid-main"><div>${chartPanel(F)}<section class="panel section-gap"><div class="panel-head"><div><h2>Weekly cash schedule</h2><p class="sub">Selected case: ${S.trinity?'with':'without'} One-time receipt · ${S.newBilling?'includes':'excludes'} future work</p></div></div><div class="table-wrap"><table><thead><tr><th>Week beginning</th><th class="money">Receipts</th><th class="money">Payments & allowances</th><th class="money">Ending cash</th></tr></thead><tbody>${F.weeks.map(x=>`<tr><td>${todayLabel(x.date)}</td><td class="money">${money(x.inflow)}</td><td class="money">${money(x.outflow)}</td><td class="money ${x.balance<0?'negative':''}"><b>${money(x.balance)}</b></td></tr>`).join('')}</tbody></table></div></section><section class="panel section-gap"><div class="panel-head"><h2>Forecast methodology</h2></div><div class="panel-body prose">${toggle('applyOverhead','Include labor + overhead allowances','Daily allocation of monthly budget; not actual bill due dates')}<div class="form-inline"><div class="field"><label for="cost-lag">Future field-cost payment lag (days)</label><input id="cost-lag" type="number" min="0" max="180" data-setting="fieldCostLag" value="${S.fieldCostLag}"></div></div><p style="margin-top:14px">Future billing is <b>incremental work after the snapshot</b>, beginning the first Friday. Collections arrive ${S.collectionLag} days later; ${100-S.margin}% field costs are paid ${S.fieldCostLag} days after billing. These are assumptions, not booked orders. Existing AR collections are separate and are counted only once.</p><p>Labor and fixed overhead use a daily allowance of <b>${money(T.monthly)} per full month</b>. Financing is dated weekly. Check actual payroll dates and already-paid October expenses before relying on intraweek cash.</p><p>Negative projected balances are funding needs, not available credit. Unscheduled AP and unknown new invoices are not silently assumed paid.</p></div></section></div>${controls()}</div>`}
function expenseView(){const T=totals();return title('Labor & fixed expenses','Switch scenarios on and off without confusing proposed cuts with completed changes.',`<button class="btn primary" data-action="new-expense">${icon('plus')}Add expense</button>`)+`<div class="stats">${stat('Monthly personnel',T.labor,'Excluded planning rows stay inactive','expenses')}${stat('Fixed overhead',T.fixed,'Excluded costs stay inactive','expenses')}${stat('Monthly cash needs',T.monthly+4*S.loan.weekly,'Includes four Financing payments','loan')}${stat('Average weekly needs',T.weekly,'Monthly costs × 12 ÷ 52 + Financing','forecast')}</div><section class="panel"><div class="table-wrap"><table class="table-full"><thead><tr><th>Cost / person</th><th>Category</th><th>Include</th><th class="money">Monthly</th><th>Source / note</th><th></th></tr></thead><tbody>${S.expenses.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.group)}</td><td><label class="toggle"><input aria-label="Include ${esc(x.name)}" type="checkbox" data-expense="${x.id}" ${x.active?'checked':''}><span></span></label></td><td class="money">${money(x.monthly)}</td><td style="max-width:320px"><span class="mini" style="font-size:10px">${esc(x.note)}</span></td><td><button class="btn" data-action="edit-expense" data-id="${x.id}">Edit</button></td></tr>`).join('')}</tbody></table></div></section><div class="notice"><b>Not a fully reconciled payroll ledger.</b> Personnel recurrence, vehicle payments, and some carried amounts need confirmation. Utilities, repairs, travel and unlisted costs are not added. Proposed cuts are only scenarios until obligations actually end. Personnel must not also be included in the field-cost margin assumption.</div>`}
function financingView(){return title('Financing & taxes','Reserve dated cash obligations before allocating optional vendor payments.',`<button class="btn" data-action="edit-loan">Edit financing inputs</button>`)+`<div class="metrics-row"><div class="metric"><label>Financing · weekly withdrawal</label><b>${money(S.loan.weekly)}</b></div><div class="metric"><label>Four payments / five payments</label><b style="font-size:20px">${whole(4*S.loan.weekly)} / ${whole(5*S.loan.weekly)}</b></div><div class="metric"><label>Contractual remaining payments · needs verification</label><b>${whole(S.loan.remaining)}</b></div></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Upcoming loan withdrawals</h2></div><table><thead><tr><th>Date</th><th class="money">Cash out</th></tr></thead><tbody>${planEvents().filter(x=>x.kind==='Financing').slice(0,8).map(x=>`<tr><td>${longDate(x.date)}</td><td class="money">${money(x.outflow)}</td></tr>`).join('')}</tbody></table></section><section class="panel"><div class="panel-head"><h2>Taxes & one-time commitments</h2></div><div class="panel-body">${S.oneoffs.map(x=>`<div class="notice"><b>${esc(x.name)}</b><br>${money(x.amount)} · ${longDate(x.date)}<br><span class="pill ${x.paid?'green':'amber'}">${x.paid?'Recorded paid':'Still included in forecast'}</span><div class="actions" style="margin-top:12px"><button class="btn" data-action="edit-oneoff" data-id="${x.id}">Edit / record status</button></div></div>`).join('')}<div class="notice">${esc(S.loan.note)} No early payoff discount is modeled. This is not an authoritative lender payoff balance.</div></div></section></div>`}
function filesView(){return title('Files & reports','Your documents belong in the folders. The ledger drives the dashboard.',`<a class="btn primary" href="${esc(S.root)}" target="_blank" rel="noopener noreferrer">Open Google Drive ↗</a>`)+`<div class="readiness">${icon('folder')}<div><strong>The six Drive folders have been created.</strong><br>The website is a local preview. Google authentication, live ledger sync, and partner invitation are not connected here. Uploads need review before they affect the totals.</div></div>${folderCards()}<div class="two-col section-gap"><section class="panel"><div class="panel-head"><h2>Workspace & sharing</h2></div><div class="panel-body prose"><p>The intended team is <b>you and Randy Thompson</b>. This preview does not grant access to anyone or broaden Drive sharing.</p><p>Keep financial files restricted. A Google invitation for your partner still needs to be completed through your account; a shared website also needs authenticated access.</p><div class="actions"><a class="btn" href="${esc(S.sheet)}" target="_blank" rel="noopener noreferrer">Open existing Google Sheet ↗</a><button class="btn" data-action="export">Export local data ↓</button></div><div class="notice">The preview and the Google Sheet are <b>not synchronized</b>. Do not edit both as competing sources of truth.</div></div></section><section class="panel"><div class="panel-head"><h2>Review & backup</h2></div><div class="panel-body prose"><p>Export a JSON backup to retain this preview's edits and scenarios. Import only a backup exported by this application. Imports replace the local working state.</p><div class="actions"><button class="btn" data-action="import">Import backup ↑</button><button class="btn" data-action="report">Print review</button></div><div class="notice">JSON and printed reports contain confidential company figures. Store and share them only with authorized reviewers.</div></div></section></div>`}
function reviewView(){return title('Reconciliation & assumptions','Decisions are only as reliable as the underlying numbers.')+`<section class="panel"><div class="panel-body" style="padding-top:8px">${S.review.map((x,i)=>`<div class="review-item"><div class="review-number">${i+1}</div><div>${esc(x)}</div></div>`).join('')}</div></section><div class="notice">Seed totals are calculated from individual entries: ${money(totals().ap)} AP, ${money(totals().ar)} AR. Notes distinguish user-confirmed payments from carried-forward figures. No identities or loan classifications are inferred from names.</div>`}
function historyView(){return title('Activity','Working-plan activity. Shared saves also appear in the Sheet audit log.',`<button class="btn danger" data-action="reset">Reset working plan</button>`)+`<section class="panel"><div class="panel-body" style="padding-top:5px">${S.activity.map(x=>`<div class="timeline-entry"><time>${esc(x.at.slice(0,16).replace('T',' '))}</time><p>${esc(x.text)}</p></div>`).join('')}</div></section>`}
function render(){nav();const views={overview,forecast:forecastView,ar:()=>invoiceView('ar'),ap:()=>invoiceView('ap'),expenses:expenseView,financing:financingView,files:filesView,review:reviewView,history:historyView};document.getElementById('main').innerHTML=(views[page]||overview)();document.querySelector('.top-actions .pill').textContent='Working snapshot · '+todayLabel(S.asOf)+', '+S.asOf.slice(0,4);}
function go(p){page=p;q='';render();document.querySelector('.sidebar').classList.remove('show');window.scrollTo({top:0,behavior:'smooth'})}
function field(name,label,value,type='text',options=null,full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label>${options?`<select id="f-${name}" name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'step="0.01" min="0"':''} ${['name','invoice','owner','amount'].includes(name)?'required':''}>`}</div>`}
function showModal(type,id=null,kind=null){editor={type,id,kind};let body='',label='';if(type==='bank'){label='Update snapshot and cash floor';body=field('bank','Cash balance ($)',S.bank/100,'number')+field('asOf','Snapshot date',S.asOf,'date')+field('reserve','Minimum reserve ($)',S.reserve/100,'number')+`<p class="prose full">Use a reconciled balance. If you advance the snapshot date, confirm earlier cash events actually occurred; past-dated forecast events will not be replayed automatically.</p>`;}
else if(type==='invoice'){const x=id?S[kind].find(x=>x.id===id):{invoice:'',customer:'',vendor:'',amount:0,paid:0,date:S.asOf,status:'Submitted',expected:'',plan:'',quality:'Working balance',note:''};label=(id?'Edit ':'Add ')+(kind==='ar'?'receivable':'payable');body=field('owner',kind==='ar'?'Customer':'Vendor',x.customer||x.vendor||'')+field('invoice','Invoice number',x.invoice)+field('amount','Original amount ($)',x.amount/100,'number')+field('paid','Already applied ($)',x.paid/100,'number')+field('date','Invoice date',x.date||'','date')+field('forecast',kind==='ar'?'Expected receipt':'Planned payment',x.expected||x.plan||'','date')+field('status',kind==='ar'?'Approval status':'Evidence level',x.status||x.quality,'text',kind==='ar'?['Approved','Submitted','Disputed','Paid']:['Working balance','Verify','Provisional'])+(! (kind==='ar')?field('due','Due date (only if known)',x.due||'','date'):'')+field('note','Source / assumptions',x.note||'','text',null,true)+`<p class="prose full">Editing an invoice does not change bank cash. Use ${kind==='ar'?'Received':'Paid'} for a payment event. No bank transfers are initiated.</p>`;}
else if(type==='settle'){const x=S[kind].find(x=>x.id===id);label='Record '+(kind==='ar'?'receipt':'payment');body=`<div class="notice full" style="margin:0"><b>${esc(x.customer||x.vendor)} · ${esc(x.invoice)}</b><br>Open balance: ${money(open(x))}</div>`+field('amount','Amount applied ($)',open(x)/100,'number')+field('reference','Reference / confirmation','')+`<label class="checklabel full"><input name="impact" type="checkbox">Also ${kind==='ar'?'add to':'subtract from'} the current cash snapshot (only if not already included).</label><p class="prose full">Records a bookkeeping update only. Leave the cash box unchecked when the bank balance already includes this transaction. The corresponding forecast amount will decrease automatically.</p>`;}
else if(type==='expense'){const x=id?S.expenses.find(x=>x.id===id):{name:'',monthly:0,group:'Subscriptions',note:''};label='Edit recurring planning expense';body=field('name','Name',x.name)+field('monthly','Monthly amount ($)',x.monthly/100,'number')+field('group','Category',x.group,'text',['Personnel','Insurance','Facilities','Vehicles','Subscriptions','Other'])+field('note','Source / status',x.note,'text',null,true);}
else if(type==='loan'){label='Financing planning inputs';body=field('weekly','Weekly withdrawal ($)',S.loan.weekly/100,'number')+field('first','First payment date',S.loan.first,'date')+field('last','Last payment date / maturity',S.loan.last,'date')+field('remaining','Scheduled remaining total ($)',S.loan.remaining/100,'number')+`<p class="prose full">Use lender-confirmed dates and balances. This does not amend the loan or calculate an official early payoff.</p>`;}
else if(type==='oneoff'){const x=S.oneoffs.find(x=>x.id===id);label='One-time obligation';body=field('name','Description',x.name)+field('amount','Amount ($)',x.amount/100,'number')+field('date','Planned payment date',x.date,'date')+`<label class="checklabel full"><input name="paid" type="checkbox" ${x.paid?'checked':''}>Already paid — exclude from future forecast</label><p class="prose full">This status change does not change bank cash; update your bank snapshot separately.</p>`;}
document.getElementById('dialog-title').textContent=label;document.getElementById('dialog-body').innerHTML='<div class="form-grid">'+body+'</div>';document.getElementById('editor').showModal();}
function submitEdit(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target).entries()),E=editor,previous=structuredClone(S);try{const amount=v=>{let n=cents(v);if(!Number.isFinite(n)||n<0||n>1e11)throw Error('Enter a valid nonnegative amount.');return n},reqDate=d=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||isNaN(date(d)))throw Error('Enter a valid date.');return d};let note='';
if(E.type==='bank'){S.bank=amount(f.bank);S.reserve=amount(f.reserve);S.asOf=reqDate(f.asOf);note='Updated bank snapshot to '+money(S.bank)+' as of '+S.asOf;}
if(E.type==='invoice'){const a=amount(f.amount),p=amount(f.paid);if(p>a)throw Error('Applied payments cannot exceed the invoice amount.');if(!f.owner.trim()||!f.invoice.trim())throw Error('Customer/vendor and invoice are required.');if(S[E.kind].some(x=>x.id!==E.id&&x.invoice.toLowerCase()===f.invoice.trim().toLowerCase()&&(x.customer||x.vendor).toLowerCase()===f.owner.trim().toLowerCase()))throw Error('That vendor/customer invoice already exists.');if(E.kind==='ar'&&f.status==='Paid'&&p!==a)throw Error('Paid status requires the full amount to be applied.');const row={id:E.id||E.kind+'-'+Date.now(),invoice:f.invoice.trim(),amount:a,paid:p,date:f.date, note:f.note};if(f.date)reqDate(f.date);if(f.forecast)reqDate(f.forecast);if(E.kind==='ar')Object.assign(row,{customer:f.owner.trim(),status:f.status,statusDate:E.id?S.ar.find(x=>x.id===E.id).statusDate:S.asOf,expected:f.forecast});else Object.assign(row,{vendor:f.owner.trim(),quality:f.status,plan:f.forecast,due:f.due||''});if(E.id)S[E.kind][S[E.kind].findIndex(x=>x.id===E.id)]=row;else S[E.kind].push(row);note='Saved '+(row.customer||row.vendor)+' invoice '+row.invoice;}
if(E.type==='settle'){const x=S[E.kind].find(x=>x.id===E.id),a=amount(f.amount);if(a<=0||a>open(x))throw Error('Payment must be positive and no greater than the open balance.');x.paid+=a;if(E.kind==='ar'&&!open(x))x.status='Paid';if(f.impact)S.bank+=(E.kind==='ar'?a:-a);note='Recorded '+money(a)+' '+(E.kind==='ar'?'received from ':'paid to ')+(x.customer||x.vendor)+' · '+x.invoice+(f.reference?' · '+f.reference:'')+(f.impact?' (bank snapshot adjusted)':' (bank snapshot unchanged)');}
if(E.type==='expense'){const row={id:E.id||'exp-'+Date.now(),name:f.name,monthly:amount(f.monthly),group:f.group,note:f.note,active:E.id?S.expenses.find(x=>x.id===E.id).active:true};if(E.id)S.expenses[S.expenses.findIndex(x=>x.id===E.id)]=row;else S.expenses.push(row);note='Updated expense '+row.name;}
if(E.type==='loan'){S.loan.weekly=amount(f.weekly);S.loan.first=reqDate(f.first);S.loan.last=reqDate(f.last);S.loan.remaining=amount(f.remaining);if(S.loan.last<S.loan.first)throw Error('Last payment cannot precede first payment.');note='Updated financing assumptions';}
if(E.type==='oneoff'){const x=S.oneoffs.find(x=>x.id===E.id);x.name=f.name;x.amount=amount(f.amount);x.date=reqDate(f.date);x.paid=!!f.paid;note='Updated one-time obligation '+x.name;}
document.getElementById('editor').close();save(note);toast('Saved in this browser — not sent to the bank.');}catch(err){S=previous;toast(err.message)}}
function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action;if(a==='navigate')go(t.dataset.page);if(a==='bank')showModal('bank');if(a==='horizon'){S.forecastWeeks=Number(t.dataset.weeks);save()}if(a==='new-invoice')showModal('invoice',null,t.dataset.kind);if(a==='edit-invoice')showModal('invoice',t.dataset.id,t.dataset.kind);if(a==='settle')showModal('settle',t.dataset.id,t.dataset.kind);if(a==='edit-expense')showModal('expense',t.dataset.id);if(a==='new-expense')showModal('expense');if(a==='edit-loan')showModal('loan');if(a==='edit-oneoff')showModal('oneoff',t.dataset.id);if(a==='close-modal')document.getElementById('editor').close();if(a==='export')download('OverSite_snapshot_'+S.asOf+'.json',JSON.stringify(S,null,2),'application/json');if(a==='import')document.getElementById('import-input').click();if(a==='csv'){const F=forecast();download('OverSite_cash_forecast.csv','Date,Receipts_USD,Outflows_USD,Projected_Cash_USD\n'+F.rows.map(x=>[x.date,(x.inflow/100).toFixed(2),(x.outflow/100).toFixed(2),(x.balance/100).toFixed(2)].join(',')).join('\n'),'text/csv');}if(a==='report'){go('overview');setTimeout(()=>window.print(),100)}if(a==='reset'&&confirm('Replace this browser’s edits with the original October 13 snapshot? Export a backup first.')){S=structuredClone(SEED);save('Reset to original working snapshot');toast('Preview reset.')}if(a==='menu')document.querySelector('.sidebar').classList.toggle('show');});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.setting){const k=t.dataset.setting,moneyKeys=['weeklyBilling','trinityAmount'],dateKeys=['trinityDate'];let v=t.type==='checkbox'?t.checked:dateKeys.includes(k)?t.value:moneyKeys.includes(k)?cents(t.value):Number(t.value);if(t.type!=='checkbox'&&!dateKeys.includes(k)&&(!Number.isFinite(v)||v<0)){toast('Enter a valid value.');render();return;}S[k]=v;save('Updated scenario: '+k+' = '+v);}if(t.dataset.expense){const x=S.expenses.find(x=>x.id===t.dataset.expense);x.active=t.checked;save((x.active?'Included ':'Excluded ')+x.name+' in the scenario.');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;q=e.target.value;document.getElementById('main').innerHTML=invoiceView(page);const s=document.getElementById('search');s.focus();s.setSelectionRange(pos,pos);}if(e.target.type==='range'&&e.target.dataset.setting){const k=e.target.dataset.setting,label=e.target.parentNode.querySelector('.control-label b');label.textContent=k==='weeklyBilling'?whole(cents(e.target.value)):e.target.value+'%';}});
document.getElementById('edit-form').addEventListener('submit',submitEdit);
document.getElementById('import-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Backup is too large.');const p=JSON.parse(await file.text());if(!validState(p))throw Error('This is not a valid OverSite backup.');if(!confirm('Replace the current local snapshot with this backup?'))return;const safe=Object.assign(structuredClone(SEED),p);safe.folders=structuredClone(SEED.folders);safe.root=SEED.root;safe.sheet=SEED.sheet;S=safe;save('Imported a local backup');toast('Backup imported.');}catch(err){toast('Import failed: '+err.message)}e.target.value='';});
window.addEventListener('storage',e=>{if(e.key===STORAGE&&e.newValue){try{const p=JSON.parse(e.newValue);if(validState(p)){S=p;render();toast('Updated from another tab in this browser.')}}catch(e){}}});
window.OverSite={getState:()=>structuredClone(S),totals,forecast,planEvents};
/* V2 daily planning layer. No bank actions or remote sync is performed. */
let selectedMonth=S.asOf.slice(0,7),selectedDay=S.asOf,burnRange='month',undoStates=[],intakeBucket='AP',folderWatch=null;
const originalRender=render, originalShowModal=showModal, originalSubmit=submitEdit, originalExpenses=expenseView, originalFiles=filesView;
function initBurn(){
 S.cashEntries??=[];S.eventChanges??={};S.intake??=[];S.forecastWeeks=Math.max(26,S.forecastWeeks||13);
 for(const x of S.expenses){if(x.cadence)continue;x.cadence='Allowance';x.start=S.asOf;x.end='';
 }
}
initBurn();
function checkpoint(){undoStates.push(structuredClone(S));if(undoStates.length>30)undoStates.shift();}
function monthStart(m){return m+'-01'}
function monthEnd(m){const d=date(m+'-01');d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(0);return iso(d)}
function nextMonth(m,n=1){const d=date(m+'-01');d.setUTCMonth(d.getUTCMonth()+n);return iso(d).slice(0,7)}
function monthLabel(m){return date(m+'-01').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'})}
function cadMatches(x,d){if(d<(x.start||S.asOf)||x.end&&d>x.end)return false;let dt=date(d),anchor=date(x.start||S.asOf),day=dt.getUTCDate();
 if(x.cadence==='Allowance')return true;
 if(x.cadence==='Once')return d===x.start;
 if(x.cadence==='Weekly')return days(d,x.start)%7===0;
 if(x.cadence==='Twice monthly')return day===1||day===15;
 return day===Math.min(anchor.getUTCDate(),date(monthEnd(d.slice(0,7))).getUTCDate());
}
function occurrenceAmount(x,d){if(x.cadence==='Allowance')return dailyAllowance(d,x.monthly);if(x.cadence==='Twice monthly')return Math.floor(x.monthly/2)+(date(d).getUTCDate()===15?x.monthly%2:0);if(x.cadence==='Weekly')return Math.round(x.monthly*12/52);return x.monthly;}
planEvents=function(withTrinity=S.trinity,keepSkipped=false){const end=addDays(S.asOf,Math.max(26,S.forecastWeeks)*7-1),ev=[];
 function push(d,kind,name,inflow,outflow,source,refType,refId){if(!d)return;const key=refType+':'+refId+':'+d,change=S.eventChanges[key]||{};let shifted=change.date||d;
  if(shifted<S.asOf||shifted>end)return;if(change.skip&&!keepSkipped)return;
  ev.push({date:shifted,originalDate:d,kind,name,inflow:change.inflow??inflow,outflow:change.outflow??outflow,source,refType,refId,key,skip:!!change.skip});}
 for(const x of S.ar){if(!open(x)||!x.expected||x.status==='Paid'||x.disabled)continue;let allowed=x.status==='Approved'||x.status==='Submitted'&&S.pending||x.status==='Disputed'&&S.disputed;if(allowed)push(addDays(x.expected,S.extraDelay||0),'AR',x.customer+' · '+x.invoice,open(x),0,x.status==='Approved'?'Approved · estimated receipt':'Conditional · not approved','ar',x.id);}
 for(const x of S.ap){if(open(x)&&x.plan&&!x.disabled)push(x.plan,'AP',x.vendor+' · '+x.invoice,0,open(x),'Planned invoice payment','ap',x.id);}
 let remaining=S.loan.remaining;if(S.loan.active!==false)for(let d=S.loan.first;d<=end&&d<=S.loan.last;d=addDays(d,7)){if(d<S.asOf)continue;let n=Math.min(S.loan.weekly,remaining);if(n<=0)break;push(d,'Financing','Financing weekly ACH',0,n,'Scheduled loan withdrawal','loan','aspire');remaining-=n;}
 for(const x of S.oneoffs){if(!x.paid&&x.active!==false)push(x.date,'Tax / other',x.name,0,x.amount,x.note||'One-time obligation','oneoff',x.id);}
 if(withTrinity)push(S.trinityDate,'Scenario','One-time receipt · potential receipt',S.trinityAmount,0,'Scenario only · no confirmed payout','trinity','trinity');
 if(S.newBilling){let bill=S.asOf;while(date(bill).getUTCDay()!==5)bill=addDays(bill,1);for(;bill<=end;bill=addDays(bill,7)){push(addDays(bill,S.collectionLag),'New work','New weekly billing collected',S.weeklyBilling,0,'Scenario · billed '+bill+'; cash '+S.collectionLag+' days later','new-receipt',bill);push(addDays(bill,S.fieldCostLag),'Field costs','Direct costs of new work',0,Math.round(S.weeklyBilling*(100-S.margin)/100),'Scenario · incremental work only','new-cost',bill);}}
 if(S.applyOverhead)for(const x of S.expenses.filter(x=>x.active))for(let d=S.asOf;d<=end;d=addDays(d,1)){if(cadMatches(x,d))push(d,x.group==='Personnel'?'Labor':'Overhead',x.name,0,occurrenceAmount(x,d),x.cadence==='Allowance'?'Daily budget allowance · due date unverified':x.cadence+' planning schedule · '+(x.note||'Verify due date'),'expense',x.id);}
 for(const x of S.cashEntries){if(x.active!==false)push(x.date,x.category,x.name,x.direction==='In'?x.amount:0,x.direction==='Out'?x.amount:0,x.note||'Manual forecast entry','cash',x.id);}
 return ev.sort((a,b)=>a.date.localeCompare(b.date)||b.inflow-a.inflow||a.name.localeCompare(b.name));
};
forecast=function(trinity=S.trinity){const events=planEvents(trinity),end=addDays(S.asOf,Math.max(26,S.forecastWeeks)*7-1);let balance=S.bank;const map={};for(const x of events)(map[x.date]??=[]).push(x);let rows=[];
 for(let d=S.asOf;d<=end;d=addDays(d,1)){const items=map[d]||[],inflow=sum(items.map(x=>x.inflow)),outflow=sum(items.map(x=>x.outflow)),opening=balance;balance+=inflow-outflow;rows.push({date:d,inflow,outflow,opening,balance,events:items,operating:sum(items.filter(x=>['Labor','Overhead','Tax / other','Tax','Field costs','Other'].includes(x.kind)).map(x=>x.outflow)),debtVendor:sum(items.filter(x=>['AP','Financing'].includes(x.kind)).map(x=>x.outflow))});}
 let weeks=[];for(let i=0;i<rows.length;i+=7){const rs=rows.slice(i,i+7);weeks.push({date:rs[0].date,end:rs.at(-1).date,inflow:sum(rs.map(x=>x.inflow)),outflow:sum(rs.map(x=>x.outflow)),balance:rs.at(-1).balance});}
 const negative=rows.find(x=>x.balance<0)?.date,breach=rows.find(x=>x.balance<S.reserve)?.date;
 return {rows,events,weeks,end:balance,min:Math.min(S.bank,...rows.map(x=>x.balance)),negative,breach,runway:negative?Math.max(0,days(negative,S.asOf)):rows.length};
};
function runCards(F){const first=S.asOf.slice(0,7),cards=[0,1,2].map(n=>{const m=nextMonth(first,n),rs=F.rows.filter(x=>x.date.startsWith(m)),val=rs.at(-1)?.balance??S.bank;return `<button class="run-card ${selectedMonth===m?'selected':''}" data-burn="month" data-month="${m}"><label>${n===0?'THIS MONTH':n===1?'NEXT MONTH':'MONTH AFTER'} · ${date(m+'-01').toLocaleDateString('en-US',{month:'short',timeZone:'UTC'}).toUpperCase()}</label><b class="${val<0?'negative':'positive'}">${whole(val)}</b><small>Projected month-end cash →</small></button>`}).join('');
 return `<div class="runway-top"><button class="run-card" data-action="bank"><label>STARTING BANK CASH</label><b>${whole(S.bank)}</b><small>${todayLabel(S.asOf)} snapshot · Edit balance</small></button><div class="run-card runway" title="Calendar days from the snapshot until the first negative daily closing balance. Based only on included scheduled items. Not a guarantee of solvency."><label>FUNDED RUNWAY</label><b>${F.negative?F.runway:'182+'} days</b><small>${F.negative?'First shortfall '+todayLabel(F.negative):'No shortfall in 182-day model'}</small></div>${cards}</div>`;
}
function dayDetail(F){let row=F.rows.find(x=>x.date===selectedDay);if(!row)return '';let all=planEvents(S.trinity,true).filter(x=>x.date===selectedDay);
 return `<section class="panel day-detail"><div class="panel-head"><div><div class="eyebrow">DAILY PAYMENT CAPACITY</div><h2>${longDate(selectedDay)}</h2></div></div><div class="panel-body"><div class="day-totals"><div><label>Opening cash</label><b>${whole(row.opening)}</b></div><div><label>Closing cash</label><b class="${row.balance<0?'negative':'positive'}">${whole(row.balance)}</b></div><div><label>Headroom today*</label><b>${whole(Math.max(0,row.balance-S.reserve))}</b></div><div><label>To restore reserve</label><b class="${row.balance<S.reserve?'negative':''}">${whole(Math.max(0,S.reserve-row.balance))}</b></div></div><p class="mini-label">Toggle a line to test deferring it</p>${all.length?all.map(x=>`<div class="event-row ${x.skip?'excluded':''}"><input aria-label="Include ${esc(x.name)} on ${x.date}" type="checkbox" data-burn-event="${esc(x.key)}" ${x.skip?'':'checked'}><div class="event-body"><b>${esc(x.name)}</b><small>${esc(x.source)}</small><button class="edit-link" data-burn="edit-event" data-key="${esc(x.key)}">Edit amount / move date</button></div><span class="event-amt ${x.inflow?'positive':''}">${x.inflow?'+':'−'}${money(x.inflow||x.outflow)}</span></div>`).join(''):'<div class="empty">No included cash items on this date.</div>'}<div class="event-details-actions"><button class="btn primary small" data-burn="add" data-date="${selectedDay}" data-direction="Out">+ Payment</button><button class="btn small" data-burn="add" data-date="${selectedDay}" data-direction="In">+ Receipt</button></div><div class="day-help">*Closing cash minus the ${whole(S.reserve)} reserve. <b>Not permission to spend:</b> later payments can still cause a shortfall. Unchecking a payment changes only the scenario; it does not pay, cancel, or forgive a bill.</div></div></section>`;
}
function burnView(){initBurn();const F=forecast(),lastMonth=F.rows.at(-1).date.slice(0,7);if(selectedMonth<S.asOf.slice(0,7)||selectedMonth>lastMonth)selectedMonth=S.asOf.slice(0,7);let rows=burnRange==='month'?F.rows.filter(x=>x.date.startsWith(selectedMonth)):F.rows.slice(0,Number(burnRange));if(!rows.some(x=>x.date===selectedDay))selectedDay=rows[0]?.date||S.asOf;
 const inc=sum(rows.map(x=>x.inflow)),out=sum(rows.map(x=>x.outflow)),unscheduled=sum(S.ap.filter(x=>!x.plan).map(open)),r=totals();const safe=F.rows.slice(F.rows.findIndex(x=>x.date===selectedDay)).reduce((a,x)=>Math.min(a,x.balance),Infinity)-S.reserve;
 return title('Daily burn sheet','See how long cash lasts — and change what happens next.',`<button class="btn" data-burn="undo" ${undoStates.length?'':'disabled'}>↶ Undo</button><button class="btn" data-burn="settings">Scenario settings</button><button class="btn primary" data-burn="add" data-direction="Out">+ Add cash item</button>`)+runCards(F)+
 `<div class="scenario-strip"><label class="scenario-chip"><input type="checkbox" data-setting="trinity" ${S.trinity?'checked':''}>One-time receipt ${whole(S.trinityAmount)} · ${todayLabel(S.trinityDate)}</label><label class="scenario-chip"><input type="checkbox" data-setting="pending" ${S.pending?'checked':''}>Submitted AR</label><label class="scenario-chip"><input type="checkbox" data-setting="disputed" ${S.disputed?'checked':''}>Disputed AR forecast</label><label class="scenario-chip"><input type="checkbox" data-setting="newBilling" ${S.newBilling?'checked':''}>New billing ${whole(S.weeklyBilling)}/week · ${S.collectionLag}d lag</label><span class="spacer"></span><button class="text-btn" data-action="navigate" data-page="expenses">Edit recurring bills →</button></div>
 <div class="alert burn-alert">${icon('warning')}<div><b>${F.negative?'Cash needs funding by '+todayLabel(F.negative)+'.':'No modeled shortfall within the horizon.'}</b> ${F.breach?'Below your '+whole(S.reserve)+' reserve on '+todayLabel(F.breach)+'. ':''}${whole(unscheduled)} of AP has no payment date and is <b>not</b> in the burn sheet. Some bill dates are allowances, not confirmed withdrawals.</div></div>
 <section class="panel"><div class="month-chart-title"><div><h2>Cash across the next six months</h2><p class="sub">Solid: with One-time receipt · Dashed: without One-time receipt · Both use the selected billing and expense settings</p></div><button class="text-btn" data-action="bank">Edit cash / reserve</button></div><div class="burn-chart">${chartHtml(F)}</div></section>
 <div class="burn-grid"><div class="burn-main"><section class="panel"><div class="panel-head"><div class="month-nav"><button class="btn small" data-burn="month-back" aria-label="Previous month">‹</button><h2>${burnRange==='month'?monthLabel(selectedMonth):'Next '+burnRange+' days'}</h2><button class="btn small" data-burn="month-next" aria-label="Next month">›</button></div><div class="month-totals"><span>Cash in<strong>${whole(inc)}</strong></span><span>Cash out<strong>${whole(out)}</strong></span><span>Period net<strong class="${inc-out<0?'negative':'positive'}">${whole(inc-out)}</strong></span></div></div><div class="toolbar" style="padding-top:0"><div class="range-tabs">${[['month','By month'],['14','14 days'],['30','30 days'],['90','90 days']].map(([k,l])=>`<button data-burn="range" data-range="${k}" class="${burnRange===k?'active':''}">${l}</button>`).join('')}</div><button class="text-btn" data-action="csv">Export daily CSV ↓</button></div><div class="burn-table-scroll"><table class="burn-table"><thead><tr><th>Date</th><th class="money">Opening</th><th class="money">Money in</th><th class="money">Money out</th><th class="money">Ending cash</th><th class="money">Above reserve</th><th>Items</th></tr></thead><tbody>${rows.map(x=>`<tr class="day-row ${x.date===selectedDay?'selected':''} ${x.balance<0?'negative-day':x.balance<S.reserve?'low':''}" data-burn="day" data-date="${x.date}" tabindex="0" role="button" aria-label="View ${x.date} cash items"><td><strong>${todayLabel(x.date)}</strong><span class="mini">${date(x.date).toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'})}</span></td><td class="money">${money(x.opening)}</td><td class="money ${x.inflow?'positive':''}">${x.inflow?money(x.inflow):'<span class="quiet">—</span>'}</td><td class="money">${x.outflow?money(x.outflow):'<span class="quiet">—</span>'}</td><td class="money"><strong class="${x.balance<0?'balance-negative':'balance-ok'}">${money(x.balance)}</strong></td><td class="money ${x.balance<S.reserve?'negative':''}">${money(x.balance-S.reserve)}</td><td><span class="pill neutral">${x.events.length} →</span></td></tr>`).join('')}</tbody></table></div><div class="burn-foot">Click any day to change that day's receipts and payments. Dates are planning assumptions. Negative balances show missing funding, not available credit. Daily allowances reserve cash; they are not actual bank transactions.</div></section><div class="notice">Runway measures days until the <b>first negative closing balance</b>. Monthly cards are month-end balances, not profits. At ${S.margin}% field margin, new work costs ${100-S.margin}% and collects after ${S.collectionLag} days. Current AR is counted at face value once. Unscheduled AP, unknown utilities, and unentered field expenses can shorten runway.</div></div>${dayDetail(F)}</div>`;
}
function expenseGrid(){initBurn();const T=totals();return title('Recurring bills & labor','Pause a cost, change its payment date, or add a new recurring expense.',`<button class="btn primary" data-burn="expense">+ Add recurring expense</button>`)+`<div class="stats">${stat('Monthly labor',T.labor,'Active planning rows','expenses')}${stat('Monthly fixed bills',T.fixed,'Active planning rows','expenses')}${stat('Four Financing payments',S.loan.weekly*4,'Actual Friday cash dates','loan')}${stat('Monthly modeled total',T.monthly+4*S.loan.weekly,'Before field costs and old AP','money')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Included</th><th>Expense</th><th class="money">Monthly budget</th><th>Timing</th><th>Starting / ending</th><th>Actions</th></tr></thead><tbody>${S.expenses.map(x=>`<tr class="${x.active?'':'event-disabled'}"><td><label class="toggle"><input type="checkbox" data-expense="${x.id}" ${x.active?'checked':''} aria-label="Include recurring ${esc(x.name)}"><span></span></label></td><td><strong>${esc(x.name)}</strong><span class="mini">${esc(x.group)}</span></td><td class="money">${money(x.monthly)}</td><td>${esc(x.cadence)}${x.cadence==='Allowance'?'<span class="mini">Not an actual payment date</span>':''}</td><td>${x.start?todayLabel(x.start):'Snapshot'}${x.end?' – '+todayLabel(x.end):' onward'}</td><td><div class="actions"><button class="btn small" data-burn="expense" data-id="${x.id}">Edit</button><button class="btn small danger" data-burn="remove-expense" data-id="${x.id}">Remove</button></div></td></tr>`).join('')}</tbody></table></div></section><div class="notice">A daily allowance spreads the monthly budget evenly through the calendar. Use Monthly / Twice monthly / Weekly when you know the payout date. Pausing or removing a row changes this <b>scenario only</b>, not the actual obligation. Annual and holiday adjustments are not assumed. Personnel included here must not also be counted within field costs.</div>`;}
function openBurnModal(type,payload={}){editor={type:'burn-'+type,...payload};let body='',label='';
 if(type==='add'){const x=payload.id?S.cashEntries.find(x=>x.id===payload.id):{name:'',date:payload.date||selectedDay||S.asOf,amount:0,direction:payload.direction||'Out',category:'Other',note:''};label=payload.id?'Edit cash item':'Add a cash item';body=field('name','Description',x.name)+field('direction','Money direction',x.direction,'text',['Out','In'])+field('amount','Payment / receipt amount ($)',x.amount/100,'number')+field('date','Cash date',x.date,'date')+field('category','Category',x.category,'text',['Other','Labor','Overhead','Tax','Financing','Field costs'])+field('note','Notes / source',x.note,'text',null,true)+`<p class="prose full">One-time scenario entry, not an executed payment. For a new vendor bill or customer invoice, use AP or AR instead. Never add a second cash entry for an invoice already scheduled.</p>`;}
 if(type==='event'){const x=planEvents(S.trinity,true).find(x=>x.key===payload.key);if(!x)return;label='Edit this occurrence';body=`<div class="notice full" style="margin:0"><b>${esc(x.name)}</b><br>${esc(x.source)}</div>`+field('date','Move cash date',x.date,'date')+field('amount','Cash amount ($)',(x.inflow||x.outflow)/100,'number')+`<label class="checklabel full"><input name="skip" type="checkbox" ${x.skip?'checked':''}>Exclude this occurrence from the scenario</label><p class="prose full">This edits only the cash forecast. An AP balance is not reduced unless you record an actual payment in AP. To change every recurring occurrence, edit the expense.</p>`;}
 if(type==='expense'){const x=payload.id?S.expenses.find(x=>x.id===payload.id):{name:'',monthly:0,group:'Other',cadence:'Monthly',start:S.asOf,end:'',note:'',active:true};label='Recurring expense schedule';body=field('name','Expense / person',x.name)+field('group','Category',x.group,'text',['Personnel','Insurance','Facilities','Vehicles','Subscriptions','Other'])+field('monthly','Monthly budget ($)',x.monthly/100,'number')+field('cadence','Timing',x.cadence,'text',['Allowance','Monthly','Twice monthly','Weekly','Once'])+field('start','First date / start date',x.start,'date')+field('end','Stop after (optional)',x.end,'date')+field('note','Source / timing notes',x.note,'text',null,true)+`<p class="prose full">Monthly pays on the start-date day each month. Twice monthly pays half on the 1st and 15th. Weekly uses monthly × 12 ÷ 52, beginning on the start date. Allowance divides the budget by days in each month. Once uses the amount as a single payment.</p>`;}
 if(type==='settings'){label='Forecast assumptions';body=field('weeklyBilling','Future weekly billing ($)',S.weeklyBilling/100,'number')+field('margin','Field gross margin (%)',S.margin,'number')+field('collectionLag','New billing collection lag (days)',S.collectionLag,'number')+field('fieldCostLag','New field-cost payment lag (days)',S.fieldCostLag,'number')+field('extraDelay','Extra delay on existing AR (days)',S.extraDelay,'number')+field('trinityDate','One-time receipt expected date',S.trinityDate,'date')+field('trinityAmount','One-time receipt amount ($)',S.trinityAmount/100,'number')+`<p class="prose full">Weekly billing controls apply only when New billing is enabled. Future receipts do not arrive on the billing day. Existing invoice balances remain separate.</p>`;}
 document.getElementById('dialog-title').textContent=label;document.getElementById('dialog-body').innerHTML='<div class="form-grid">'+body+'</div>';document.getElementById('editor').showModal();}
submitEdit=function(e){if(!editor?.type.startsWith('burn-'))return originalSubmit(e);e.preventDefault();const f=Object.fromEntries(new FormData(e.target).entries()),E=editor;try{const amt=x=>{const n=cents(x);if(!Number.isSafeInteger(n)||n<0||n>1e11)throw Error('Enter a valid nonnegative amount.');return n},d=x=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(x)||Number.isNaN(date(x).getTime()))throw Error('Choose a valid date.');return x};let note='';checkpoint();
 if(E.type==='burn-add'){if(!f.name.trim())throw Error('Enter a description.');const x={id:E.id||'cash-'+Date.now(),name:f.name.trim(),date:d(f.date),amount:amt(f.amount),direction:f.direction,category:f.category,note:f.note,active:true};if(!x.amount)throw Error('Amount must be greater than zero.');if(E.id)S.cashEntries[S.cashEntries.findIndex(r=>r.id===E.id)]=x;else S.cashEntries.push(x);note='Saved cash item '+x.name;}
 if(E.type==='burn-event'){const ev=planEvents(S.trinity,true).find(x=>x.key===E.key);const n=amt(f.amount);S.eventChanges[E.key]={date:d(f.date),skip:!!f.skip,inflow:ev.inflow?n:0,outflow:ev.inflow?0:n};note='Changed occurrence '+ev.name+' on '+ev.originalDate;}
 if(E.type==='burn-expense'){if(!f.name.trim())throw Error('Enter a name.');const x={id:E.id||'exp-'+Date.now(),name:f.name.trim(),monthly:amt(f.monthly),group:f.group,cadence:f.cadence,start:d(f.start),end:f.end?d(f.end):'',note:f.note,active:E.id?S.expenses.find(x=>x.id===E.id).active:true};if(x.end&&x.end<x.start)throw Error('End date must follow start date.');if(E.id)S.expenses[S.expenses.findIndex(r=>r.id===E.id)]=x;else S.expenses.push(x);note='Updated recurring schedule for '+x.name;}
 if(E.type==='burn-settings'){const values={weeklyBilling:amt(f.weeklyBilling),margin:Number(f.margin),collectionLag:Number(f.collectionLag),fieldCostLag:Number(f.fieldCostLag),extraDelay:Number(f.extraDelay),trinityDate:d(f.trinityDate),trinityAmount:amt(f.trinityAmount)};if(values.margin<0||values.margin>100)throw Error('Margin must be 0–100.');for(const k of ['collectionLag','fieldCostLag','extraDelay'])if(!Number.isInteger(values[k])||values[k]<0||values[k]>365)throw Error('Lags must be whole days between 0 and 365.');Object.assign(S,values);note='Updated forecast assumptions';}
 if(E.type==='burn-intake'){acceptIntake(E.id,f);note='Reviewed document '+E.id;}
 document.getElementById('editor').close();save(note);toast('Burn sheet updated. No payments sent.');}catch(err){const prev=undoStates.pop();if(prev)S=prev;toast(err.message);}};
document.getElementById('edit-form').removeEventListener('submit',originalSubmit);document.getElementById('edit-form').addEventListener('submit',submitEdit);
render=function(){initBurn();nav();const item=document.querySelector('[data-action="navigate"][data-page="overview"]');if(item)item.innerHTML=icon('forecast')+'Daily burn sheet';const fileItem=document.querySelector('nav [data-page="files"]');if(fileItem)fileItem.innerHTML=icon('folder')+'Folders & intake';const views={overview:burnView,forecast:burnView,ar:()=>invoiceView('ar'),ap:()=>invoiceView('ap'),expenses:expenseGrid,financing:financingView,files:intakeView,review:reviewView,history:historyView};document.getElementById('main').innerHTML=(views[page]||burnView)();document.querySelector('.top-actions .pill').textContent='Snapshot · '+todayLabel(S.asOf)+', '+S.asOf.slice(0,4);if(page==='overview'||page==='forecast')document.getElementById('bread-current').textContent='Daily burn sheet';};
document.addEventListener('click',e=>{const t=e.target.closest('[data-burn]');if(!t)return;const a=t.dataset.burn;
 if(a==='day'){selectedDay=t.dataset.date;render();}
 if(a==='month'){selectedMonth=t.dataset.month;burnRange='month';render();}
 if(a==='month-next'||a==='month-back'){selectedMonth=nextMonth(selectedMonth,a==='month-next'?1:-1);burnRange='month';render();}
 if(a==='range'){burnRange=t.dataset.range;render();}
 if(a==='add')openBurnModal('add',{id:t.dataset.id,date:t.dataset.date,direction:t.dataset.direction});
 if(a==='edit-event')openBurnModal('event',{key:t.dataset.key});
 if(a==='expense')openBurnModal('expense',{id:t.dataset.id});
 if(a==='settings')openBurnModal('settings');
 if(a==='remove-expense'&&confirm('Remove this recurring row from the scenario? This does not cancel the real expense.')){checkpoint();S.expenses=S.expenses.filter(x=>x.id!==t.dataset.id);save('Removed recurring expense from forecast');}
 if(a==='undo'&&undoStates.length){S=undoStates.pop();save('Undid last forecast change');toast('Change undone');}
 if(a==='upload'){intakeBucket=t.dataset.bucket;document.getElementById('documents-input').click();}
 if(a==='review-file')reviewIntake(t.dataset.id);
 if(a==='remove-file'){checkpoint();S.intake=S.intake.filter(x=>x.id!==t.dataset.id);save('Removed intake item');}
 if(a==='folder-pick'){intakeBucket=t.dataset.bucket||'AP';pickLocalFolder();}
});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.burnEvent){checkpoint();const k=t.dataset.burnEvent;S.eventChanges[k]={...S.eventChanges[k],skip:!t.checked};save((t.checked?'Restored ':'Paused ')+k);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.day-row')){e.preventDefault();e.target.click();}});
// Honest local document intake: CSV/TSV/TXT are parsed; PDFs/images require manual extraction.
function intakeView(){return title('Folders & document intake','Drop files into AR, AP, or Expenses. Review extracted fields before they affect the burn sheet.',`<a class="btn" href="${esc(S.root)}" target="_blank" rel="noopener">Open Drive folder ↗</a><button class="btn" data-burn="folder-pick" data-bucket="AP">Choose local AP folder</button>`)+`<div class="intake-status"><div><b>Local intake works here.</b> CSV, TSV and text invoices are parsed in your browser. PDFs and images are queued for manual review. Approved rows update the ledger and burn sheet.</div><span class="pill amber">Google Drive auto-scan: not connected</span></div><div class="intake-grid">${S.folders.map(x=>`<section class="intake-card"><h3>${icon('folder').replace('<svg','<svg style="width:18px;height:18px;vertical-align:middle;margin-right:6px"')} ${esc(x.name)}</h3><p>${esc(x.description)}</p><a href="${esc(x.url)}" target="_blank" rel="noopener">Open Google Drive folder ↗</a><div class="dropzone" tabindex="0" role="button" data-burn="upload" data-bucket="${esc(x.name)}" data-drop="${esc(x.name)}">+ Drop documents here or choose files<br><span class="mini">CSV / TSV / TXT parsed · other files need review</span></div></section>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><div><h2>Review queue</h2><p class="sub">${S.intake.length} items · nothing posts automatically</p></div><span class="pill neutral">${folderWatch?'Local folder checks while open':'Manual upload active'}</span></div><div class="table-wrap"><table class="intake-table"><thead><tr><th>Document</th><th>Folder</th><th>Extracted invoice</th><th class="money">Amount</th><th>Status</th><th>Review</th></tr></thead><tbody>${S.intake.length?S.intake.map(x=>`<tr><td><strong>${esc(x.filename)}</strong><span class="mini">${esc(x.party||'Party not identified')}</span></td><td>${esc(x.bucket)}</td><td>${esc(x.invoice||'Needs entry')}</td><td class="money">${x.amount?money(x.amount):'—'}</td><td><span class="pill ${x.status==='Posted'?'green':x.status==='Duplicate'?'red':'amber'}">${esc(x.status)}</span></td><td>${x.status==='Posted'?'In ledger':`<button class="btn small" data-burn="review-file" data-id="${x.id}">Review</button>`}<button class="text-btn" data-burn="remove-file" data-id="${x.id}">Remove</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No documents imported. Drop a CSV or text invoice into a folder above.</td></tr>'}</tbody></table></div></section><div class="notice">Local folder monitoring requires a browser supporting folder access and runs <b>only while this page stays open</b>. It is not a Google Drive watcher. Live Drive scanning, cloud PDF extraction, shared edits and sign-in are not deployed. Source documents remain on your device; only reviewed fields are saved locally. No private data is sent to an external parser.</div><div class="actions section-gap"><button class="btn" data-action="export">Export workspace backup</button><button class="btn" data-action="import">Import workspace backup</button></div>`;}
function parseCSV(text,sep=','){const out=[];let row=[],v='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===sep&&!quoted){row.push(v.trim());v='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v.trim());if(row.some(Boolean))out.push(row);row=[];v='';}else v+=c;}row.push(v.trim());if(row.some(Boolean))out.push(row);return out;}
function asDate(s){s=(s||'').trim();if(/^\d{4}-\d{2}-\d{2}$/.test(s))return s;const m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);if(m)return (m[3].length===2?'20'+m[3]:m[3])+'-'+m[1].padStart(2,'0')+'-'+m[2].padStart(2,'0');return '';}
function parseDoc(text,name){const lines=parseCSV(text,name.endsWith('.tsv')?'\t':',');if(lines.length>1){const h=lines[0].map(x=>x.toLowerCase().replace(/[^a-z]/g,''));const idx=keys=>h.findIndex(x=>keys.includes(x));const i=idx(['invoice','invoicenumber','invoiceid','invoiceno']),a=idx(['amount','total','balance','amountdue','totalamount']),p=idx(['vendor','customer','company','party','name']),d=idx(['date','invoicedate']),due=idx(['duedate','expecteddate','paymentdate']);if(i>=0&&a>=0)return lines.slice(1,501).map(r=>({invoice:r[i]||'',amount:cents((r[a]||'0').replace(/[^\d.-]/g,'')),party:p>=0?r[p]||'':'',date:d>=0?asDate(r[d]):'',expected:due>=0?asDate(r[due]):''}));}
 const inv=text.match(/invoice\s*(?:number|no\.?|#)?\s*[:#-]?\s*([A-Za-z0-9][\w-]*)/i),am=text.match(/(?:total\s*(?:amount\s*)?due|balance\s*due|amount\s*due|total\s*amount|total)\s*[:$\s]*([\d,]+\.\d{2})/i),party=text.match(/(?:vendor|customer|company|payee)\s*(?:name)?\s*:\s*([^\n\r]+)/i),dt=text.match(/(?:invoice\s*date|date)\s*:\s*(\d{4}-\d{2}-\d{2}|\d{1,2}\/\d{1,2}\/\d{2,4})/i);return [{invoice:inv?.[1]||'',amount:am?cents(am[1].replace(/,/g,'')):0,party:party?.[1]?.trim()||'',date:asDate(dt?.[1]||'')}];}
async function ingestFiles(files,bucket){let count=0;for(const file of Array.from(files).slice(0,60)){if(file.size>10e6){toast('Skipped '+file.name+': over 10 MB');continue;}const fp=[bucket,file.webkitRelativePath||file.name,file.size,file.lastModified].join('|');if(S.intake.some(x=>x.fingerprint===fp))continue;const ext=file.name.split('.').pop().toLowerCase(),parse=['csv','tsv','txt'].includes(ext);let rows=parse?parseDoc(await file.text(),file.name.toLowerCase()):[{}];for(const r of rows){const dest=bucket==='AR'?'ar':'ap',dupe=r.invoice&&S[dest].some(x=>x.invoice.toLowerCase()===r.invoice.toLowerCase()&&(x.customer||x.vendor).toLowerCase()===(r.party||'').toLowerCase());S.intake.push({id:'doc-'+Date.now()+'-'+count,filename:file.name,bucket,fingerprint:fp,party:r.party||'',invoice:r.invoice||'',amount:Number.isFinite(r.amount)?r.amount:0,date:r.date||'',expected:r.expected||'',status:dupe?'Duplicate':parse?'Needs review':'Needs extraction',note:parse?'Locally extracted; verify all fields.':'This format is not parsed in the browser. Enter verified fields manually.'});count++;}}save('Added '+count+' items to document review');toast(count+' items queued for review; no ledger entries created.');}
function reviewIntake(id){const x=S.intake.find(x=>x.id===id);editor={type:'burn-intake',id};document.getElementById('dialog-title').textContent='Review before posting';document.getElementById('dialog-body').innerHTML='<div class="form-grid">'+`<div class="notice full" style="margin:0"><b>${esc(x.filename)}</b><br>${esc(x.note)}</div>`+field('dest','Post to',x.bucket==='AR'?'AR':x.bucket==='Expenses'?'Expense':'AP','text',['AR','AP','Expense'])+field('party','Customer / vendor / expense',x.party)+field('invoice','Invoice / reference',x.invoice)+field('amount','Open amount ($)',x.amount/100,'number')+field('date','Invoice date',x.date,'date')+field('expected','Cash date (optional)',x.expected||'','date')+`<p class="prose full">Check the source document. Duplicates are blocked by party + invoice. AR is posted as Submitted, not approved or paid. Without a cash date the entry remains unscheduled.</p></div>`;document.getElementById('editor').showModal();}
function acceptIntake(id,f){const x=S.intake.find(x=>x.id===id),n=cents(f.amount);if(!f.party.trim()||!f.invoice.trim()||!Number.isSafeInteger(n)||n<=0)throw Error('Party, reference, and a positive amount are required.');if(f.expected&&!/^\d{4}-\d{2}-\d{2}$/.test(f.expected))throw Error('Check cash date.');const dest=f.dest==='AR'?'ar':'ap';if(f.dest!=='Expense'&&S[dest].some(r=>r.invoice.toLowerCase()===f.invoice.trim().toLowerCase()&&(r.customer||r.vendor).toLowerCase()===f.party.trim().toLowerCase()))throw Error('This party + invoice already exists. Reconcile it instead of duplicating it.');if(f.dest==='Expense'){S.cashEntries.push({id:'cash-'+id,name:f.party+' · '+f.invoice,date:f.expected||'',amount:n,direction:'Out',category:'Overhead',note:'Imported from '+x.filename,active:true});}else{const row={id:dest+'-'+id,invoice:f.invoice.trim(),date:f.date||'',amount:n,paid:0,note:'Reviewed import from '+x.filename};if(dest==='ar')Object.assign(row,{customer:f.party.trim(),status:'Submitted',statusDate:S.asOf,expected:f.expected||''});else Object.assign(row,{vendor:f.party.trim(),quality:'Verify',plan:f.expected||'',due:''});S[dest].push(row);}x.status='Posted';}
async function pickLocalFolder(){if(!window.showDirectoryPicker){toast('Local folder monitoring is not supported here. Use folder drop zones to choose files.');return;}try{const handle=await window.showDirectoryPicker({mode:'read'});let scan=async()=>{const fs=[];for await(const ent of handle.values())if(ent.kind==='file')fs.push(await ent.getFile());await ingestFiles(fs,intakeBucket)};if(folderWatch)clearInterval(folderWatch);await scan();folderWatch=setInterval(()=>scan().catch(()=>{clearInterval(folderWatch);folderWatch=null;toast('Folder access ended. Choose it again.')}),30000);render();toast('Local folder selected. Checks run every 30 seconds while open.');}catch(e){if(e.name!=='AbortError')toast('Folder access failed. Try choosing files instead.');}}
const documentsInput=document.createElement('input');documentsInput.type='file';documentsInput.id='documents-input';documentsInput.multiple=true;documentsInput.hidden=true;document.body.append(documentsInput);documentsInput.addEventListener('change',async e=>{await ingestFiles(e.target.files,intakeBucket);e.target.value='';});
document.addEventListener('dragover',e=>{const z=e.target.closest('[data-drop]');if(z){e.preventDefault();z.classList.add('dragover')}});document.addEventListener('dragleave',e=>e.target.closest('[data-drop]')?.classList.remove('dragover'));document.addEventListener('drop',e=>{const z=e.target.closest('[data-drop]');if(!z)return;e.preventDefault();z.classList.remove('dragover');ingestFiles(e.dataTransfer.files,z.dataset.drop)});
window.OverSite={getState:()=>structuredClone(S),totals,forecast,planEvents};
/* v3 strategy layer — one dated cash engine, independent invoice balances,
   inspectable months, occurrence edits, conserved splits, and source-date aging. */
const V3_STORE='oversite-strategy-burn-v3';
const CREDIT_FOLDER=SEED.folders.find(f=>f.name==='Credit apps')||{name:'Credit apps',url:SEED.root};
const deep=x=>JSON.parse(JSON.stringify(x));
const V3_SEED=deep(SEED);
if(!V3_SEED.folders.some(x=>x.name==='Credit apps'))V3_SEED.folders.push(CREDIT_FOLDER);
let baselineV3=null,scenariosV3=[],scenarioName='Working plan',v3Filter='all',v3Search='',v3Selected=new Set(),v3Expanded=new Set(),v3Redo=[],v3LastChange=null,v3Cached=null,v3Modal=null,v3IntakeType='AP';
const dateOK=x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!isNaN(date(x))&&iso(date(x))===x;
const fridayOnOrAfter=d=>{while(date(d).getUTCDay()!==5)d=addDays(d,1);return d;};
function initV3(){initBurn();S.planV3??={};S.gapsV3??={};S.monthsV3??=6;S.lookaheadV3??=30;S.billingStartV3??=fridayOnOrAfter(S.asOf);S.creditAppsV3??=[];S.agingAsOfV3??=S.asOf;S.activity??=[];
 S.folders=deep(V3_SEED.folders);
 for(const x of S.ar){x.termsDays??=(window.OverSiteDefaults?.customerTerms?.[x.customer]??45);x.termsBasis??='Invoice date (assumed)';x.contactNote??='';}
}
try{const raw=OSLocalMemory.getItem(V3_STORE);if(raw){const o=JSON.parse(raw);if(validState(o.state)){S=o.state;baselineV3=o.baseline;scenariosV3=o.scenarios||[];scenarioName=o.name||scenarioName;}}}catch(e){console.warn(e)}
initV3();baselineV3=baselineV3||deep(S);let committedV3=deep(S);page='forecast';
function persistV3(){try{OSLocalMemory.setItem(V3_STORE,JSON.stringify({state:S,baseline:baselineV3,scenarios:scenariosV3,name:scenarioName}));}catch(e){toast('Storage unavailable or full. Export a backup before closing.');}}
checkpoint=function(){};
function monthAbbr(m){return date(m+'-01').toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})}
function cadenceV3(x,d,s){if(d<(x.start||s.asOf)||x.end&&d>x.end)return false;const n=Number(d.slice(8));if(x.cadence==='Allowance')return true;if(x.cadence==='Once')return d===x.start;if(x.cadence==='Weekly')return days(d,x.start)%7===0;if(x.cadence==='Twice monthly')return n===1||n===15;return n===Math.min(Number((x.start||s.asOf).slice(8)),Number(monthEnd(d.slice(0,7)).slice(8)));}
function modelV3(s=S,tri=s.trinity){
 const start=s.asOf,end=monthEnd(nextMonth(start.slice(0,7),(s.monthsV3||6)-1)),dates=[];for(let d=start;d<=end;d=addDays(d,1))dates.push(d);
 const units=[],events=[];
 const add=x=>units.push(Object.assign({family:'cash',refId:'',parts:[],enabled:true,priority:'Review',confidence:'Estimated',note:'',due:'',allowance:false},x));
 for(const x of s.ar){if(!open(x)||x.status==='Paid')continue;const enabled=x.status==='Approved'||x.status==='Submitted'&&s.pending||x.status==='Disputed'&&s.disputed||x.forecastInclude===true;
 add({key:'ar:'+x.id,family:'ar',refId:x.id,name:x.customer,reference:x.invoice,kind:'AR',direction:'In',amount:open(x),parts:x.expected?[{date:addDays(x.expected,s.extraDelay||0),originalDate:x.expected,amount:open(x)}]:[],enabled:enabled&&!x.disabled,reason:enabled?'Invoice paused':x.status+' receipts switched off',confidence:x.status==='Approved'?'Approved · date estimated':x.status+' · conditional',note:x.note,priority:'Collection'});}
 for(const x of s.ap){if(open(x))add({key:'ap:'+x.id,family:'ap',refId:x.id,name:x.vendor,reference:x.invoice,kind:'AP',direction:'Out',amount:open(x),parts:x.plan?[{date:x.plan,amount:open(x)}]:[],enabled:!x.disabled,reason:'Invoice paused',confidence:x.quality||'Working balance',note:x.note,due:x.due,priority:x.vendor==='Boss'?'Committed':'Review'});}
 let rem=s.loan.remaining;if(!Number.isSafeInteger(rem))rem=0;
 for(let d=s.loan.first;d<=end&&d<=s.loan.last;d=addDays(d,7)){if(d<start)continue;const n=Math.min(s.loan.weekly,rem);if(n<=0)break;add({key:'loan:'+d,family:'loan',refId:'aspire',name:'Financing',reference:'Weekly ACH',kind:'Financing',direction:'Out',amount:n,parts:[{date:d,amount:n}],enabled:s.loan.active!==false,confidence:'Scheduled ACH',priority:'Protected',due:d,note:'Moving this entry does not change the lender’s automatic withdrawal.'});rem-=n;}
 for(const x of s.oneoffs){if(!x.paid)add({key:'oneoff:'+x.id,family:'oneoff',refId:x.id,name:x.name,reference:'One-time obligation',kind:'Tax / other',direction:'Out',amount:x.amount,parts:x.date?[{date:x.date,amount:x.amount}]:[],enabled:x.active!==false,confidence:'User amount · verify date',priority:'Protected',due:x.date,note:x.note});}
 add({key:'trinity',family:'trinity',refId:'trinity',name:'One-time receipt',reference:'Potential one-time receipt',kind:'Scenario',direction:'In',amount:s.trinityAmount,parts:[{date:s.trinityDate,amount:s.trinityAmount}],enabled:!!tri,reason:'One-time receipt is switched off',confidence:'Unconfirmed',priority:'Collection',note:'No confirmed invoice or payout. Not recurring revenue.'});
 if(s.newBilling){for(let bill=s.billingStartV3||fridayOnOrAfter(start);bill<=end;bill=addDays(bill,7)){
  const n=s.weeklyBilling,c=Math.round(n*(100-s.margin)/100);add({key:'new-receipt:'+bill,family:'new-receipt',refId:bill,name:'Future weekly work',reference:'Billed '+bill,kind:'New work',direction:'In',amount:n,parts:[{date:addDays(bill,s.collectionLag),amount:n}],confidence:'Forecast only',priority:'Collection',note:'Incremental work, not existing AR. Billing collects after '+s.collectionLag+' days.'});add({key:'new-cost:'+bill,family:'new-cost',refId:bill,name:'Direct costs of new work',reference:'Billed '+bill,kind:'Field costs',direction:'Out',amount:c,parts:[{date:addDays(bill,s.fieldCostLag),amount:c}],confidence:'Forecast only',priority:'Operating',note:(100-s.margin)+'% field costs; not a second deduction for existing vendor AP.'});}}
 for(const x of s.expenses){const dd=dates.filter(d=>cadenceV3(x,d,s));
  if(x.cadence==='Allowance'){for(const m of [...new Set(dd.map(d=>d.slice(0,7)))]){const pp=dd.filter(d=>d.startsWith(m)).map(d=>({date:d,amount:dailyAllowance(d,x.monthly)}));add({key:'budget:'+x.id+':'+m,family:'expense',refId:x.id,name:x.name,reference:monthAbbr(m)+' budget allowance',kind:x.group==='Personnel'?'Labor':'Overhead',direction:'Out',amount:sum(pp.map(p=>p.amount)),parts:pp,enabled:x.active&&s.applyOverhead,reason:!x.active?'Recurring cost paused':'Labor & overhead switched off',confidence:'Allowance · date unknown',allowance:true,note:x.note,priority:x.group==='Personnel'?'Operating':'Review'});}}
  else for(const d of dd){const n=occurrenceAmount(x,d);add({key:'expense:'+x.id+':'+d,family:'expense',refId:x.id,name:x.name,reference:x.cadence+' installment',kind:x.group==='Personnel'?'Labor':'Overhead',direction:'Out',amount:n,parts:[{date:d,amount:n}],enabled:x.active&&s.applyOverhead,reason:!x.active?'Recurring cost paused':'Labor & overhead switched off',confidence:'Planning date · verify',note:x.note,priority:x.group==='Personnel'?'Operating':'Review'});}
 }
 for(const x of s.cashEntries){if(!x.settled)add({key:'cash:'+x.id,family:'cash',refId:x.id,name:x.name,reference:x.reference||'Manual cash item',kind:x.category||'Other',direction:x.direction,amount:x.amount,parts:x.date?[{date:x.date,amount:x.amount}]:[],enabled:x.active!==false,reason:'Manual item paused',note:x.note,confidence:'Manual estimate',priority:x.priority||'Flexible'});}
 for(const [key,ov] of Object.entries(s.planV3||{})){if(units.some(u=>u.key===key)||!ov.parts?.some(p=>p.date>=start)||!key.startsWith('expense:')&&!key.startsWith('budget:'))continue;const ref=key.split(':')[1],x=s.expenses.find(x=>x.id===ref);if(!x)continue;add({key,family:'expense',refId:ref,name:x.name,reference:ov.sourceReference||'Rescheduled earlier installment',kind:x.group==='Personnel'?'Labor':'Overhead',direction:'Out',amount:ov.sourceAmount??sum(ov.parts.map(p=>p.amount)),parts:[],enabled:x.active&&s.applyOverhead,confidence:'Carried-forward plan',note:ov.note||x.note,priority:x.group==='Personnel'?'Operating':'Review'});}
 for(const u of units){u.originalParts=deep(u.parts);u.sourceEnabled=u.enabled;const ov=s.planV3?.[u.key];if(ov){u.parts=deep(ov.parts??u.parts);u.enabled=u.enabled&&(ov.enabled??true);u.note=ov.note||u.note;u.allowance=u.allowance&&!ov.parts;}
  // Retain v2 occurrence changes when a v3 plan has not superseded them.
  if(!ov)for(const p of u.parts){const k=u.family+':'+u.refId+':'+(p.originalDate||p.date),old=s.eventChanges?.[k]||s.eventChanges?.[u.family+':'+u.refId+':'+p.date];if(old){p.date=old.date||p.date;p.skip=!!old.skip;p.amount=u.direction==='In'?(old.inflow??p.amount):(old.outflow??p.amount);}}
  u.unassigned=Math.max(0,u.amount-sum(u.parts.map(p=>p.amount)));u.overallocated=Math.max(0,sum(u.parts.map(p=>p.amount))-u.amount);
  u.parts.forEach((p,i)=>{if(!p.date)return;const enabled=u.enabled&&!p.skip&&p.amount>0;events.push({key:u.key+'|'+i,unitKey:u.key,index:i,date:p.date,originalDate:p.originalDate||u.originalParts[i]?.date||p.date,name:u.name,reference:u.reference,kind:u.kind,amount:p.amount,inflow:u.direction==='In'?p.amount:0,outflow:u.direction==='Out'?p.amount:0,direction:u.direction,source:u.confidence,confidence:u.confidence,enabled,skip:!enabled,reason:!u.enabled?(ov?.enabled===false?'Excluded in this scenario':u.reason||'Excluded'):p.skip?'Occurrence excluded':'',family:u.family,refType:u.family,refId:u.refId,allowance:u.allowance,priority:u.priority,due:u.due,note:u.note});});
 }
 const all=events.sort((a,b)=>a.date.localeCompare(b.date)||b.inflow-a.inflow||a.name.localeCompare(b.name)),ev=all.filter(e=>e.enabled&&e.date>=start&&e.date<=end),map={};for(const e of ev)(map[e.date]??=[]).push(e);let cash=s.bank;
 const rows=dates.map(d=>{const es=map[d]||[],inflow=sum(es.map(e=>e.inflow)),outflow=sum(es.map(e=>e.outflow)),opening=cash;cash+=inflow-outflow;return{date:d,opening,inflow,outflow,balance:cash,trough:opening-outflow,events:es,operating:sum(es.filter(e=>!['AP','Financing'].includes(e.kind)).map(e=>e.outflow)),debtVendor:sum(es.filter(e=>['AP','Financing'].includes(e.kind)).map(e=>e.outflow))};});
 const months=[...new Set(rows.map(r=>r.date.slice(0,7)))].map(m=>{const rr=rows.filter(r=>r.date.startsWith(m));return{month:m,opening:rr[0].opening,inflow:sum(rr.map(r=>r.inflow)),outflow:sum(rr.map(r=>r.outflow)),balance:rr.at(-1).balance,min:Math.min(rr[0].opening,...rr.map(r=>r.balance)),firstNegative:rr.find(r=>r.balance<0)?.date,rows:rr};});
 const weeks=[];for(let i=0;i<rows.length;i+=7){const rr=rows.slice(i,i+7);weeks.push({date:rr[0].date,end:rr.at(-1).date,inflow:sum(rr.map(r=>r.inflow)),outflow:sum(rr.map(r=>r.outflow)),balance:rr.at(-1).balance});}
 const negative=rows.find(r=>r.balance<0)?.date,breach=rows.find(r=>r.balance<s.reserve)?.date;
 const unscheduled=sum(units.filter(u=>u.family==='ap').map(u=>Math.max(0,u.amount-sum(all.filter(e=>e.unitKey===u.key&&e.enabled&&e.date>=start).map(e=>e.amount)))));
 return{start,endDate:end,rows,months,weeks,events:ev,all,units,min:Math.min(s.bank,...rows.map(r=>r.balance)),end:cash,negative,breach,runway:negative?Math.max(0,days(negative,start)):rows.length,unscheduled,stale:all.filter(e=>e.enabled&&e.date<start),beyond:all.filter(e=>e.enabled&&e.date>end)};
}
forecast=function(tri=S.trinity){return modelV3(S,tri)};
planEvents=function(tri=S.trinity,keepSkipped=false){const f=modelV3(S,tri);return keepSkipped?f.all.filter(e=>e.date>=S.asOf&&e.date<=f.endDate):f.events};
save=function(text){initV3();const before=modelV3(committedV3);if(JSON.stringify(S)!==JSON.stringify(committedV3)){undoStates.push(deep(committedV3));if(undoStates.length>35)undoStates.shift();v3Redo=[];}if(text){S.activity.unshift({at:new Date().toISOString(),text});S.activity=S.activity.slice(0,200);}const after=modelV3(S);v3LastChange=text?{text,runway:after.runway-before.runway,deltas:after.months.slice(0,3).map(m=>({month:m.month,value:m.balance-(before.months.find(b=>b.month===m.month)?.balance??m.balance)}))}:v3LastChange;committedV3=deep(S);persistV3();render();};
function modifyV3(text,fn){const old=deep(S);try{fn();if(!validState(S))throw Error('Invalid financial data.');save(text);}catch(e){S=old;toast(e.message);render();}}
function undoV3(){if(!undoStates.length)return;v3Redo.push(deep(S));S=undoStates.pop();committedV3=deep(S);v3LastChange=null;initV3();persistV3();render();toast('Undone. All forecasts recalculated.');}
function redoV3(){if(!v3Redo.length)return;undoStates.push(deep(S));S=v3Redo.pop();committedV3=deep(S);v3LastChange=null;initV3();persistV3();render();}
const btnV3=(txt,a,attrs='',cls='btn')=>`<button type="button" class="${cls}" data-v3="${a}" ${attrs}>${txt}</button>`;
const unitV3=k=>(v3Cached||modelV3(S)).units.find(u=>u.key===k);
function setPlanV3(key,parts,enabled,note){const u=unitV3(key);if(!u)throw Error('This entry no longer exists.');for(const p of parts){if(!dateOK(p.date)||!Number.isSafeInteger(p.amount)||p.amount<0)throw Error('Enter a valid date and nonnegative amount.');}if(['ap','ar'].includes(u.family)&&sum(parts.map(p=>p.amount))>u.amount)throw Error('Planned allocations cannot exceed the open invoice balance.');S.planV3[key]={parts:deep(parts),enabled:enabled??u.enabled,note:note??u.note};}
function statsV3(F){return `<div class="runway-top">${btnV3(`<label>STARTING CASH</label><b>${money(S.bank)}</b><small>${todayLabel(S.asOf)} snapshot · edit cash</small>`,'bank','','run-card')}<button type="button" class="run-card runway" data-home-fix="runway" title="See the first shortfall day and the cash items behind it"><label>FUNDED RUNWAY</label><b>${F.negative?F.runway:F.rows.length+'+'} days</b><small>${F.negative?'First negative close '+todayLabel(F.negative):'No negative close in this horizon'}<br>Reserve breached: ${F.breach?todayLabel(F.breach):'not in horizon'}</small></button>${F.months.slice(0,3).map((m,i)=>btnV3(`<label>${['THIS MONTH','NEXT MONTH','MONTH AFTER'][i]} · ${monthAbbr(m.month).toUpperCase()}</label><b class="${m.balance<0?'negative':'positive'}">${money(m.balance)}</b><small>In ${whole(m.inflow)} · out ${whole(m.outflow)}<br>Click to see every item →</small>`,'month',`data-month="${m.month}"`,'run-card '+(selectedMonth===m.month?'selected':''))).join('')}</div>`;}
function controlsV3(){return `<div class="scenario-strip">${[['trinity','One-time receipt '+whole(S.trinityAmount)],['pending','Submitted AR'],['disputed','Disputed AR / disputed'],['newBilling','Future weekly work'],['applyOverhead','Labor & overhead']].map(([k,l])=>`<label class="scenario-chip"><input type="checkbox" data-setting="${k}" ${S[k]?'checked':''}>${l}</label>`).join('')}<span class="spacer"></span>${btnV3('Assumptions','settings')}${btnV3('Undo','undo',undoStates.length?'':'disabled')}${btnV3('Redo','redo',v3Redo.length?'':'disabled')}</div><div class="model-context"><span>${S.newBilling?`${money(S.weeklyBilling)}/week · ${S.margin}% margin · receipts +${S.collectionLag} days / costs +${S.fieldCostLag} days`:'Future weekly work is OFF. Rate and margin affect cash only when this switch is on.'}</span><span>Recalculated ${new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',second:'2-digit'})}</span></div>`;}
function deltaV3(){return v3LastChange?`<div class="delta-strip"><b>${esc(v3LastChange.text)}</b><span>${v3LastChange.deltas.map(d=>monthAbbr(d.month)+': '+(d.value>0?'+':'')+money(d.value)).join(' · ')} · Runway ${v3LastChange.runway>=0?'+':''}${v3LastChange.runway} days</span></div>`:'';}
function monthHeadV3(F){const m=F.months.find(x=>x.month===selectedMonth);return `<section class="panel month-explanation"><div class="panel-head"><div><div class="eyebrow">${selectedMonth===S.asOf.slice(0,7)?'REMAINING MONTH · FROM '+todayLabel(S.asOf).toUpperCase():'FULL MONTH'}</div><h2>${monthLabel(selectedMonth)} · where the money goes</h2></div><div class="actions">${btnV3('‹','month-prev')}<select data-v3-select="month" aria-label="Select month">${F.months.map(m=>`<option value="${m.month}" ${m.month===selectedMonth?'selected':''}>${monthLabel(m.month)}</option>`).join('')}</select>${btnV3('›','month-next')}${btnV3('Export items','export-month')}</div></div><div class="month-equation"><div><label>Opening cash</label><b>${money(m.opening)}</b></div><span>+</span><div><label>Money in</label><b class="positive">${money(m.inflow)}</b></div><span>−</span><div><label>Money out</label><b>${money(m.outflow)}</b></div><span>=</span><div><label>Closing cash</label><b class="${m.balance<0?'negative':'positive'}">${money(m.balance)}</b></div></div><div class="recon-line"><span>${m.opening+m.inflow-m.outflow===m.balance?'✓ Reconciles to the included cash items below':'⚠ Reconciliation error'}</span><span>Lowest daily close ${money(m.min)}${m.firstNegative?' · first shortfall '+todayLabel(m.firstNegative):''}</span></div></section>`;}
function graphV3(F){const m=F.months.find(m=>m.month===selectedMonth),r=m.rows,b=modelV3(baselineV3),br=r.map(x=>b.rows.find(z=>z.date===x.date)?.balance??x.balance),w=1000,h=170,L=72,R=20,T=14,B=28;let lo=Math.min(0,S.reserve,...r.map(x=>x.balance),...br),hi=Math.max(0,S.reserve,...r.map(x=>x.balance),...br);if(hi===lo)hi++;const pad=(hi-lo)*.12;lo-=pad;hi+=pad;const x=i=>L+(w-L-R)*i/Math.max(1,r.length-1),y=v=>T+(hi-v)/(hi-lo)*(h-T-B),path=a=>a.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ');let grid='';for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;grid+=`<line x1="${L}" x2="${w-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e7ecef"/><text x="${L-9}" y="${y(v)+4}" text-anchor="end" fill="#879ba6" font-size="10">${whole(Math.round(v))}</text>`;}return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Daily cash balance for ${esc(monthLabel(selectedMonth))}">${grid}<line x1="${L}" x2="${w-R}" y1="${y(S.reserve)}" y2="${y(S.reserve)}" stroke="#c09d62" stroke-dasharray="4 4"/><path d="${path(br)}" fill="none" stroke="#97a8b4" stroke-dasharray="5 5" stroke-width="1.5"/><path d="${path(r.map(z=>z.balance))}" fill="none" stroke="#087d73" stroke-width="2.5"/>${r.map((z,i)=>`<circle data-v3="day" data-date="${z.date}" tabindex="0" role="button" aria-label="${z.date} ${money(z.balance)}" cx="${x(i)}" cy="${y(z.balance)}" r="3.5" fill="${z.balance<0?'#b84649':'#087d73'}"><title>${z.date}: ${money(z.balance)} · ${z.events.length} items</title></circle>${i%7===0||i===r.length-1?`<text x="${x(i)}" y="${h-6}" text-anchor="middle" fill="#879ba6" font-size="10">${todayLabel(z.date)}</text>`:''}`).join('')}</svg>`;}
function monthItemsV3(F){const items=[],groups={};for(const e of F.all.filter(e=>e.date>=S.asOf&&e.date.startsWith(selectedMonth))){if(e.allowance){const k=e.unitKey+':'+e.enabled;if(!groups[k]){groups[k]={...e,rowId:k,grouped:true,indices:[],dates:[],amount:0,inflow:0,outflow:0};items.push(groups[k]);}const g=groups[k];g.indices.push(e.index);g.dates.push(e.date);g.amount+=e.amount;g.inflow+=e.inflow;g.outflow+=e.outflow;}else items.push({...e,rowId:e.key,indices:[e.index],dates:[e.date]});}return items.sort((a,b)=>a.date.localeCompare(b.date)||b.inflow-a.inflow||a.name.localeCompare(b.name));}
function filteredV3(F){return monthItemsV3(F).filter(e=>(v3Filter==='off'?!e.enabled:e.enabled&&(v3Filter==='all'||e.direction===v3Filter))&&`${e.name} ${e.reference} ${e.kind}`.toLowerCase().includes(v3Search.toLowerCase()));}
function itemRowV3(e){return `<tr class="${e.enabled?'':'event-disabled'}"><td><input type="checkbox" aria-label="Select ${esc(e.name+' '+e.reference)}" data-v3-check="${esc(e.rowId)}" ${v3Selected.has(e.rowId)?'checked':''}></td><td>${e.grouped?btnV3(`Daily allowance<small>${e.dates.length} budget days ▾</small>`,'plan',`data-key="${esc(e.unitKey)}"`,'allowance-btn'):`<input type="date" class="row-date" data-v3-date="${esc(e.unitKey)}" data-index="${e.index}" value="${e.date}" aria-label="Cash date ${esc(e.name+' '+e.reference)}">`}</td><td><strong>${esc(e.name)}</strong><span class="mini">${esc(e.reference)}</span><span class="tiny">${esc(e.kind)}${e.due&&e.date>e.due?' · '+days(e.date,e.due)+' days after due date':''}</span></td><td><span class="pill ${/conditional|Unconfirmed/.test(e.confidence)?'amber':'neutral'}">${esc(e.confidence)}</span>${!e.enabled?`<span class="mini">${esc(e.reason)}</span>`:''}${e.priority==='Protected'?'<span class="mini">Protected obligation</span>':''}</td><td class="money positive">${e.direction==='In'?money(e.amount):'—'}</td><td class="money">${e.direction==='Out'?money(e.amount):'—'}</td><td class="row-actions">${btnV3('Move / split','plan',`data-key="${esc(e.unitKey)}" data-index="${e.grouped?'':e.index}"`,'btn small')}${btnV3(e.enabled?'Exclude':'Include','toggle',`data-key="${esc(e.unitKey)}" data-index="${e.grouped?'':e.index}"`,'text-btn')}${e.grouped?btnV3(v3Expanded.has(e.rowId)?'Hide days':'Show days','expand',`data-row="${esc(e.rowId)}"`,'text-btn'):''}</td></tr>${e.grouped&&v3Expanded.has(e.rowId)?`<tr><td colspan="7" class="expanded-days">${e.indices.map(i=>{const x=v3Cached.all.find(a=>a.unitKey===e.unitKey&&a.index===i);return btnV3(todayLabel(x.date)+`<b>${money(x.amount)}</b>`,'plan',`data-key="${esc(x.unitKey)}" data-index="${i}"`)}).join('')}</td></tr>`:''}`;}
function ledgerV3(F){const rows=filteredV3(F);return `<section class="panel ledger-v3"><div class="toolbar"><div class="segmented">${[['all','All included'],['In','Money in'],['Out','Money out'],['off','Excluded']].map(([k,l])=>btnV3(l,'filter',`data-filter="${k}"`,v3Filter===k?'on':'')).join('')}</div><input id="v3-search" type="search" placeholder="Find an invoice, vendor or expense…" value="${esc(v3Search)}" aria-label="Filter cash items"><div class="actions">${btnV3('+ Receipt','add','data-dir="In"')}${btnV3('+ Payment','add','data-dir="Out"','btn primary')}</div></div><div class="bulk-bar"><b>${v3Selected.size} selected</b>${btnV3('+7 days','bulk-seven','','text-btn')}${btnV3('Move selected…','bulk','','text-btn')}${btnV3('Clear selection','clear-selection','','text-btn')}<small>Changing the cash date does not change contractual due dates or amounts owed.</small></div><div class="table-wrap"><table class="monthly-ledger"><thead><tr><th><input type="checkbox" aria-label="Select displayed items" data-v3-select-all></th><th>Cash date</th><th>Item / reference</th><th>Evidence / status</th><th class="money">In</th><th class="money">Out</th><th>Strategy controls</th></tr></thead><tbody>${rows.map(itemRowV3).join('')||'<tr><td colspan="7" class="empty">No items match. Try All included, or add a payment or receipt.</td></tr>'}</tbody></table></div><div class="burn-foot">${rows.length} displayed lines · net of displayed included items: <b>${money(sum(rows.filter(e=>e.enabled).map(e=>e.inflow-e.outflow)))}</b>. Daily allowances are grouped by expense; expand them for each day. Filters do not change cash calculations.</div></section>`;}
function backlogV3(F){const un=F.units.filter(u=>u.family==='ap'&&Math.max(0,u.amount-sum(F.all.filter(e=>e.unitKey===u.key&&e.enabled&&e.date>=S.asOf).map(e=>e.amount)))>0);return `<details class="panel backlog-v3"><summary><div><b>${money(F.unscheduled)} of AP is outside the future cash schedule</b><small>It is still owed. Undated or excluded bills do not vanish.</small></div><span>Assign dates ↓</span></summary><div class="table-wrap"><table><thead><tr><th>Vendor / invoice</th><th class="money">Open balance</th><th>Evidence</th><th>Plan</th></tr></thead><tbody>${un.map(u=>`<tr><td><strong>${esc(u.name)}</strong><span class="mini">${esc(u.reference)}</span></td><td class="money">${money(u.amount)}</td><td>${esc(u.confidence)}</td><td>${btnV3('Schedule / split','plan',`data-key="${esc(u.key)}"`,'btn small')}</td></tr>`).join('')}</tbody></table></div></details>`;}
function forecastScreenV3(F){
 return title('Cash & runway','See where you stand. Click a month to work through its receipts and bills.',
  btnV3('Open detailed burn sheet →','nav','data-page="overview"','btn primary'))
  +statsV3(F)
  +`<div class="home-quick-actions"><label class="scenario-chip"><input type="checkbox" data-setting="trinity" ${S.trinity?'checked':''}>Include One-time receipt ${whole(S.trinityAmount)}</label><span class="home-case-note">${S.trinity?'With One-time receipt':'Without One-time receipt'} · ${S.newBilling?'Future work included':'Existing receivables only'} · Based on ${esc(S.asOf)}</span><span class="spacer"></span>${btnV3('Undo','undo',undoStates.length?'':'disabled')}${btnV3('+ Receipt / expense','add')}${btnV3('Save plan','save-scenario')}</div>`
  +deltaV3()
  +`<div class="home-alert"><b>${F.negative?'First projected shortfall: '+todayLabel(F.negative):'No projected shortfall in this horizon'}</b><span>${money(F.unscheduled)} of AP has no active payment date and is not funded in these balances.</span>${btnV3('Review unscheduled bills','backlog','','text-btn')}</div>`
  +`<details class="home-settings"><summary>Forecast assumptions & scenario controls</summary>${controlsV3()}</details>`
  +monthHeadV3(F)+ledgerV3(F)
  +`<details class="panel section-gap cash-chart-detail"><summary>Cash chart for ${monthAbbr(selectedMonth)} ↓</summary><div class="panel-head"><p class="sub">Your plan versus saved baseline; reserve shown separately.</p></div><div class="burn-chart">${graphV3(F)}</div></details>`
  +backlogV3(F)+riskSummaryV3(F);
}
function dayPanelV3(F){const r=F.rows.find(r=>r.date===selectedDay),es=F.all.filter(e=>e.date===selectedDay),future=F.rows.filter(z=>z.date>=selectedDay&&z.date<=addDays(selectedDay,S.lookaheadV3)),safe=Math.max(0,Math.min(...future.map(z=>z.balance))-S.reserve);return `<section class="panel day-detail"><div class="panel-head"><div><div class="eyebrow">${todayLabel(selectedDay)}</div><h2>What creates ${money(r.balance)}?</h2></div></div><div class="panel-body"><div class="day-totals"><div><label>Opening cash</label><b>${money(r.opening)}</b></div><div><label>Closing cash</label><b class="${r.balance<0?'negative':''}">${money(r.balance)}</b></div><div><label>Money in</label><b class="positive">${money(r.inflow)}</b></div><div><label>Money out</label><b>${money(r.outflow)}</b></div></div><p class="mini-label">Every payment & receipt</p>${es.map(e=>`<div class="event-row ${e.enabled?'':'excluded'}"><input type="checkbox" aria-label="Include ${esc(e.name)}" data-v3-toggle="${esc(e.unitKey)}" data-index="${e.index}" ${e.enabled?'checked':''}><div class="event-body"><b>${esc(e.name)}</b><small>${esc(e.reference)} · ${esc(e.confidence)}</small>${btnV3('Change amount / move / split','plan',`data-key="${esc(e.unitKey)}" data-index="${e.index}"`,'text-btn')}</div><span class="event-amt ${e.inflow?'positive':''}">${e.inflow?'+':'−'}${money(e.amount)}</span></div>`).join('')||'<p class="empty">No dated items today.</p>'}<div class="actions section-gap">${btnV3('+ Outgoing','add',`data-dir="Out" data-date="${selectedDay}"`)}${btnV3('+ Incoming','add',`data-dir="In" data-date="${selectedDay}"`)}</div><div class="notice"><b>${money(safe)} modeled headroom</b><br>Uses the lowest cash over the following ${S.lookaheadV3} days, less the reserve. Unscheduled bills and missing costs are not funded by this figure.</div>${r.inflow&&r.trough<0?`<div class="notice red-notice">If withdrawals clear before receipts today, cash could touch ${money(r.trough)} even if the closing balance is positive.</div>`:''}</div></section>`;}
function dailyScreenV3(F){const rr=F.rows.filter(r=>r.date.startsWith(selectedMonth));if(!rr.some(r=>r.date===selectedDay))selectedDay=rr[0].date;return title('Daily burn','Opening cash + each incoming item − each outgoing item = closing cash.',btnV3('Month item list','nav','data-page="forecast"')+btnV3('+ Cash item','add','','btn primary'))+workControlsV4()+deltaV3()+monthHeadV3(F)+`<div class="burn-grid"><section class="panel"><div class="panel-head"><h2>Day-by-day payment capacity</h2><span class="pill neutral">Click a row to inspect its items</span></div><div class="burn-table-scroll"><table class="burn-table"><thead><tr><th>Date</th><th class="money">Opening</th><th class="money">Money in</th><th class="money">Money out</th><th class="money">Closing</th><th>Items</th></tr></thead><tbody>${rr.map(r=>`<tr class="day-row ${r.date===selectedDay?'selected':''} ${r.balance<0?'negative-day':r.balance<S.reserve?'low':''}" tabindex="0" role="button" data-v3="day" data-date="${r.date}"><td><strong>${todayLabel(r.date)}</strong></td><td class="money">${money(r.opening)}</td><td class="money positive">${r.inflow?money(r.inflow):'—'}</td><td class="money">${r.outflow?money(r.outflow):'—'}</td><td class="money ${r.balance<0?'negative':''}">${money(r.balance)}</td><td>${r.events.length} →</td></tr>${r.date===selectedDay?`<tr class="day-inline"><td colspan="6">${r.events.map(e=>`<div><span>${e.inflow?'↙':'↗'} ${esc(e.name)} <small>${esc(e.reference)}</small></span><b class="${e.inflow?'positive':''}">${e.inflow?'+':'−'}${money(e.amount)}</b>${btnV3('Move / split','plan',`data-key="${esc(e.unitKey)}" data-index="${e.index}"`,'text-btn')}</div>`).join('')||'No scheduled items.'}</td></tr>`:''}`).join('')}</tbody></table></div><div class="burn-foot">Negative cash is a funding gap, not available credit. This view and Cash forecast use exactly the same cash events.</div></section>${dayPanelV3(F)}</div>`+riskSummaryV3(F);}
const MISSED_V3=[['utilities','Location utilities','Electricity, water, gas, and any extra internet are not budgeted.'],['insurance','Insurance coverage','Confirm insurance entries are not duplicates; add any other active policies.'],['vehicles','Vehicle amounts & running costs','Verify vehicle amounts against the ledger. Fuel, repairs, registration and exit costs may need separate entries.'],['labor','Labor, pay dates & job-cost overlap','Confirm personnel recurrence, unpaid installments, and whether personnel are already inside field costs.'],['taxes','Tax obligations','Only entered tax obligations are scheduled. Verify payroll taxes, sales-tax remittances and future amounts.'],['cards','Credit cards, fees & annual renewals','Card payments, bank fees, accounting, legal and annual renewals may be missing.'],['field','Field spending','Repairs, deposits, mobilization, lodging, travel and maintenance need dates if not in AP or field-cost assumptions.'],['billing','Incremental billing & collection lag','New weekly work must not duplicate existing AR. Billing is not same-day cash.'],['dates','Terms, holidays & banking cutoffs','The Net-25 starting point is unconfirmed. Check customer payout runs and cash availability.'],['old','Unreconciled old balances','Reconcile older invoice balances against evidence before adding them again.'],['bank','Bank / actual payment reconciliation','Update the snapshot and record receipts/payments once; do not deduct already posted activity twice.'],['credit','Credit applications','A requested credit limit is not cash or approved credit. Fees, guarantees and authorizations require separate review.']];
function checksV3(F){const a=[];const put=(type,title,detail,act='',attrs='')=>a.push({type,title,detail,act,attrs});
 if(F.negative){const r=F.rows.find(r=>r.date===F.negative);put('red','First cash shortfall: '+todayLabel(F.negative),`Closing cash ${money(r.balance)}. That day’s outflows include ${r.events.filter(e=>e.outflow).slice(0,4).map(e=>e.name+' '+money(e.amount)).join(', ')}.`,'day',`data-date="${F.negative}"`);}
 if(F.unscheduled)put('amber',money(F.unscheduled)+' of AP has no active future funding','It is still a liability. The cash chart only pays invoices assigned to dates.','backlog');
 const partial=F.units.filter(u=>u.family==='ap'&&u.unassigned>0&&u.parts.length);if(partial.length)put('amber','Partial payments leave remainders',partial.map(u=>u.name+' '+u.reference+': '+money(u.unassigned)+' unallocated').slice(0,4).join('; '));
 const allw=S.expenses.filter(x=>x.active&&x.cadence==='Allowance');if(allw.length)put('amber',allw.length+' bills have no verified cash date','Daily allowances smooth the cash path. Use a real date when known to expose concentrated payments.','nav','data-page="expenses"');
 const cond=F.events.filter(e=>e.inflow&&/conditional|Unconfirmed|Forecast/.test(e.confidence));if(cond.length)put('amber','Conditional receipts included: '+money(sum(cond.map(x=>x.inflow))),'These rely on approval, correction, One-time receipt, or future work. Stress-test delayed collections.','nav','data-page="strategy"');
 const stale=F.stale;if(stale.length)put('red',stale.length+' cash items are before the snapshot','They are not replayed automatically. Reconcile payment status or move their cash dates.');
 const risk=F.rows.find(r=>r.trough<0&&r.inflow&&r.balance>=0);if(risk)put('red','Same-day settlement risk: '+todayLabel(risk.date),'Debits before receipts could take cash to '+money(risk.trough)+' even though day-end cash is positive.','day',`data-date="${risk.date}"`);
 const off=F.all.filter(e=>!e.enabled&&e.priority==='Protected'&&e.date>=S.asOf);if(off.length)put('red','Protected obligations have been excluded','Scenario changes do not cancel Financing ACH or tax obligations. Confirm any arrangement separately.');
 const weekend=F.events.filter(e=>[0,6].includes(date(e.date).getUTCDay())&&!e.allowance);if(weekend.length)put('amber',weekend.length+' scheduled items fall on a weekend','Actual availability and withdrawal dates can differ. Dates are editable; bank holidays are not automatically verified.');
 if(F.units.some(u=>u.overallocated&&['ar','ap'].includes(u.family)))put('red','A plan is larger than an open invoice','Reconcile the source or reduce/split its schedule before relying on this forecast.');
 const over90=S.ap.filter(x=>open(x)&&x.date&&days(S.asOf,x.date)>90);if(over90.length)put('amber',over90.length+' vendor invoices are over 90 days old','Invoice age is not the same as days overdue. Verify terms and the actual due date.','nav','data-page="ap"');
 const orphan=Object.keys(S.planV3).filter(k=>!F.units.some(u=>u.key===k));if(orphan.length)put('amber','Stored overrides need review',orphan.length+' overrides no longer match a current item after source, date or recurrence changes.');
 if(F.beyond.length)put('amber','Items exist beyond the visible horizon',F.beyond.length+' scheduled entries are after '+longDate(F.endDate)+'. They remain saved but are not in displayed totals.');
 put('amber','Provisional AP and unpaid-status checks','Vendor statement amounts and working balances need reconciliation. No accounting or bank feed is connected.','nav','data-page="ap"');
 if(!S.newBilling)put('blue','Future billing rate is not active','Enable Future weekly work to make billing and margin assumptions affect the cash forecast. Existing AR is collected at its face value.');
 const duplicate=S.cashEntries.filter(c=>c.reference&&[...S.ar,...S.ap].some(x=>x.invoice.toLowerCase()===c.reference.toLowerCase()));if(duplicate.length)put('red','A manual item may duplicate an invoice',duplicate.map(x=>x.name).join(', ')+'. Schedule the invoice rather than posting a second cash item.');
 return a;
}
function riskSummaryV3(F){const a=checksV3(F);return `<section class="panel section-gap"><div class="panel-head"><div><h2>Strategy checks · ${a.length} issues</h2><p class="sub">Rule-based warnings, not predictions of customer behavior.</p></div>${btnV3('Review all →','nav','data-page="review"','text-btn')}</div><div class="check-summary">${a.slice(0,3).map(x=>`<div><span class="pill ${x.type}">${x.type==='red'?'Risk':'Review'}</span><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p>${x.act?btnV3('Inspect →',x.act,x.attrs,'text-btn'):''}</div>`).join('')}</div></section>`;}
function reviewScreenV3(F){const a=checksV3(F);return title('Checks & missing items','Make gaps visible before a bill surprises the bank account.',btnV3('+ Missing cash item','add','','btn primary'))+`<div class="check-summary checks-wide">${a.map(x=>`<section class="panel"><span class="pill ${x.type}">${x.type==='red'?'Needs attention':'Review'}</span><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p>${x.act?btnV3('Open detail →',x.act,x.attrs,'text-btn'):''}</section>`).join('')}</div><h2 class="section-gap">Budget-completeness checklist</h2><p class="sub">Amounts are not invented. Add a known expense or mark the question reviewed.</p><section class="panel section-gap"><table><thead><tr><th>Reviewed</th><th>Potential missing item</th><th>What to check</th><th></th></tr></thead><tbody>${MISSED_V3.map(([k,t,n])=>`<tr><td><input type="checkbox" data-v3-gap="${k}" ${S.gapsV3[k]?'checked':''} aria-label="Reviewed ${esc(t)}"></td><td><strong>${esc(t)}</strong></td><td>${esc(n)}</td><td>${btnV3('Add item','add',`data-name="${esc(t)}"`,'btn small')}</td></tr>`).join('')}</tbody></table></section>${F.stale.length?`<section class="panel section-gap"><div class="panel-head"><h2>Past-snapshot items not replayed</h2></div><table><tbody>${F.stale.map(e=>`<tr><td>${esc(e.name+' · '+e.reference)}</td><td>${e.date}</td><td class="money">${money(e.amount)}</td><td>${btnV3('Review date','plan',`data-key="${esc(e.unitKey)}" data-index="${e.index}"`,'btn small')}</td></tr>`).join('')}</tbody></table></section>`:''}`;}
function agingV3(x,ar=true){if(!open(x))return{cls:'age-paid',label:'Paid',days:0,date:'',assumed:false};let due=x.due||'',assumed=!due;
 if(!due&&ar&&x.termsBasis!=='Unknown'){const anchor=x.termsBasis?.startsWith('Approval')?x.statusDate:x.date;if(dateOK(anchor)&&Number.isFinite(x.termsDays))due=addDays(anchor,x.termsDays);}
 if(!due)return{cls:'age-unknown',label:'Due date unknown',date:'',days:null,assumed:true};const age=days(S.agingAsOfV3,due);return{cls:age>60?'age-critical':age>30?'age-old':age>0?'age-late':age>=-7?'age-soon':'age-current',label:age>0?(assumed?'Est. ':'')+age+' days late':age===0?(assumed?'Est. ':'')+'due today':'Due in '+Math.abs(age)+' days',date:due,days:age,assumed};}
function invoicesScreenV3(kind,F){const ar=kind==='ar',rows=S[kind].filter(x=>(`${x.customer||x.vendor} ${x.invoice} ${x.status||x.quality}`).toLowerCase().includes(q.toLowerCase())),ag=S[kind].map(x=>({x,a:agingV3(x,ar)})),late=sum(ag.filter(z=>z.a.days>0).map(z=>open(z.x))),soon=sum(ag.filter(z=>z.a.days!==null&&z.a.days<=0&&z.a.days>=-7).map(z=>open(z.x)));
 return title(ar?'Accounts receivable':'Accounts payable',ar?'Age the invoice, track approval separately, and plan the actual collection date.':'Source liabilities and cash plans are separate. Changing a plan does not cancel debt.',btnV3('+ Invoice','invoice',`data-kind="${kind}"`,'btn primary'))+`<div class="metrics-row"><div class="metric"><label>Outstanding ${ar?'AR':'AP'}</label><b>${money(sum(S[kind].map(open)))}</b></div><div class="metric"><label>Late by entered / estimated due date</label><b class="negative">${money(late)}</b></div><div class="metric"><label>Due within 7 days</label><b>${money(soon)}</b></div></div><div class="aging-legend"><span class="age-chip age-current">Current</span><span class="age-chip age-soon">Due in ≤7 days</span><span class="age-chip age-late">1–30 days late</span><span class="age-chip age-old">31–60 late</span><span class="age-chip age-critical">61+ late</span><span class="age-chip age-unknown">Unknown</span><label>Aging as of <input type="date" data-v3-aging value="${S.agingAsOfV3}" aria-label="Aging review date"></label>${btnV3('Use today','aging-today','','text-btn')}</div><section class="panel"><div class="toolbar"><input id="v3-invoice-search" type="search" placeholder="Search customer, vendor or invoice" value="${esc(q)}" aria-label="Search invoice ledger"><span class="pill neutral">Aging date does not move the bank snapshot</span></div><div class="table-wrap"><table class="invoice-ledger-v3"><thead><tr><th>${ar?'Customer':'Vendor'} / invoice</th><th class="money">Open amount</th><th>Due date & aging</th><th>${ar?'Approval':'Evidence'}</th><th>Planned cash</th><th>Action</th></tr></thead><tbody>${rows.map(x=>{const a=agingV3(x,ar),es=F.all.filter(e=>e.unitKey===kind+':'+x.id&&e.enabled&&e.date>=S.asOf);return `<tr class="aging-row ${a.cls}"><td><strong>${esc(x.customer||x.vendor)}</strong><span class="mini">${esc(x.invoice)} · issued ${x.date?todayLabel(x.date):'unknown'}</span></td><td class="money">${money(open(x))}</td><td><span class="age-chip ${a.cls}">${a.label}</span><span class="mini">${a.date?(a.assumed?'Estimated due ':'Due ')+a.date:'Terms need verification'}</span></td><td>${ar?statusPill(x.status):`<span class="pill neutral">${esc(x.quality||'Working balance')}</span>`}${ar&&x.status==='Disputed'?'<span class="mini">Resolve dispute before relying on receipt</span>':''}</td><td>${es.length?es.map(e=>`${todayLabel(e.date)} · ${money(e.amount)}`).join('<br>'):'Not scheduled / excluded'}${es.some(e=>a.date&&e.date>a.date)?'<span class="mini negative">Plan is later than due date</span>':''}</td><td><div class="actions">${open(x)?btnV3('Plan / split','plan',`data-key="${kind+':'+x.id}"`,'btn small'):''}${btnV3('Edit source','invoice',`data-kind="${kind}" data-id="${x.id}"`,'text-btn')}${open(x)?btnV3(ar?'Record received':'Record paid','settle',`data-kind="${kind}" data-id="${x.id}"`,'text-btn'):''}</div></td></tr>`}).join('')}</tbody></table></div></section><div class="notice">${ar?'Net 25 / Net 45 are working terms. Until you confirm the clock’s starting point, computed due dates are labeled estimates. Color uses due date, not the date you hope to collect. Approval and dispute status are separate.':'Invoice age is not overdue age. Unknown contractual due dates stay gray instead of inventing delinquency.'} A future payment plan is not an executed bank transaction.</div>`;
}
function strategyScreenV3(F){const variants=[['Working plan',deep(S)],['Existing AR 7 days later',Object.assign(deep(S),{extraDelay:(S.extraDelay||0)+7})],['Without One-time receipt',Object.assign(deep(S),{trinity:false})],['Approved AR only',Object.assign(deep(S),{trinity:false,pending:false,disputed:false,newBilling:false})]];const headroom=Math.max(0,Math.min(...F.rows.slice(0,S.lookaheadV3+1).map(r=>r.balance))-S.reserve);
 return title('Strategy & stress tests','Test timing and downside cases before turning a plan into a commitment.',btnV3('Save scenario','save-scenario','','btn primary'))+controlsV3()+`<section class="panel"><div class="panel-head"><h2>What happens when money arrives later?</h2></div><div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Runway</th>${F.months.slice(0,3).map(m=>`<th class="money">${monthAbbr(m.month)} close</th>`).join('')}<th class="money">Lowest cash</th></tr></thead><tbody>${variants.map(([n,s])=>{const f=modelV3(s);return `<tr><td>${n}</td><td>${f.negative?f.runway:f.rows.length+'+'} days</td>${f.months.slice(0,3).map(m=>`<td class="money ${m.balance<0?'negative':''}">${money(m.balance)}</td>`).join('')}<td class="money negative">${money(f.min)}</td></tr>`}).join('')}</tbody></table></div></section><div class="two-col section-gap"><section class="panel"><div class="panel-head"><h2>Test a new commitment</h2></div><div class="panel-body"><p class="prose">The payment editor shows the impact on all three month-end balances before you save. For an existing invoice, use its AP plan instead of adding a duplicate.</p>${btnV3('Test a payment','add','data-dir="Out"','btn primary')}</div></section><section class="panel"><div class="panel-head"><h2>Modeled headroom over ${S.lookaheadV3} days</h2></div><div class="panel-body"><b class="capacity-number">${money(headroom)}</b><p class="prose">Lowest projected cash through this window minus the reserve. This does not fund missing bills, unscheduled AP or amounts that depend on uncertain receipts.</p></div></section></div>`+riskSummaryV3(F);}
function historyScreenV3(F){return title('Scenarios & activity','Save alternatives, compare them, or return to your baseline.',btnV3('Save scenario','save-scenario')+btnV3('Pin working plan as baseline','baseline')+btnV3('Export backup','backup'))+`<section class="panel"><div class="panel-head"><h2>Saved scenarios</h2></div><table><thead><tr><th>Name</th><th>Saved</th><th>Actions</th></tr></thead><tbody><tr><td>Baseline</td><td>Starting or explicitly pinned snapshot</td><td>${btnV3('Load baseline','load-baseline','','btn small')}</td></tr>${scenariosV3.map((c,i)=>`<tr><td>${esc(c.name)}</td><td>${esc(c.at.slice(0,16).replace('T',' '))}</td><td>${btnV3('Load','load-scenario',`data-case="${i}"`,'btn small')}${btnV3('Remove saved copy','delete-scenario',`data-case="${i}"`,'text-btn')}</td></tr>`).join('')}</tbody></table></section><section class="panel section-gap"><div class="panel-head"><h2>Working-plan activity</h2><span class="pill neutral">Not a multiuser audit log</span></div><div class="panel-body">${S.activity.slice(0,60).map(x=>`<div class="timeline-entry"><time>${esc(x.at.slice(0,16).replace('T',' '))}</time><p>${esc(x.text)}</p></div>`).join('')}</div></section>`;}
const oldBurnModalV3=openBurnModal,oldSubmitV3=submitEdit,oldInvoiceViewV3=invoiceView,oldIntakeV3=intakeView,oldIngestV3=ingestFiles,oldReviewIntakeV3=reviewIntake;
function numberV3(v){const n=cents(v);if(!Number.isSafeInteger(n)||n<0||n>1e11)throw Error('Enter a valid nonnegative amount.');return n;}
