function creditBalanceV4(c){if(c.linkedLoan)return S.loan.remaining;const xs=S.ap.filter(x=>x.vendor===c.linkedVendor);return xs.length?sum(xs.map(open)):null;}
function creditLimitV4(c){return c.type==='Term loan'?'Not revolving':c.approvedLimit===null||c.approvedLimit===undefined?'Not provided':money(c.approvedLimit)+(c.limitConfirmed?'':' (unconfirmed)');}
function creditAvailableV4(c){if(c.type==='Term loan')return{label:'Not revolving',note:'Scheduled repayment is not borrowing availability.',amount:null};if(c.status==='Closed'||c.archived)return{label:'Closed',note:'No available-credit assumption.',amount:null};const used=creditBalanceV4(c);if(c.approvedLimit==null||!c.limitConfirmed||!c.utilizationVerified||used===null||c.status!=='Approved')return{label:'Not verified',note:'Needs approved status, confirmed limit and reconciled utilization.',amount:null};return {label:money(Math.max(0,c.approvedLimit-used)),note:used>c.approvedLimit?'Tracked use exceeds limit by '+money(used-c.approvedLimit):'Estimate from confirmed inputs. Not bank cash.',amount:Math.max(0,c.approvedLimit-used)};}
function creditMissingV4(c){const a=[];if(c.terms==='Not confirmed'||!c.terms)a.push('payment terms');if(c.type!=='Term loan'&&!c.limitConfirmed)a.push('approved limit');if(!c.contact)a.push('account contact');if(!c.sourceUrl)a.push('agreement link');return a;}
function creditVisibleV4(){return S.creditAccountsV4.filter(c=>`${c.name} ${c.status} ${c.terms} ${c.type} ${c.contact}`.toLowerCase().includes(creditQueryV4.toLowerCase())&&(creditFilterV4==='All accounts'||creditFilterV4==='Needs terms'&&(!c.terms||c.terms==='Not confirmed')||creditFilterV4==='Terms recorded'&&c.terms&&c.terms!=='Not confirmed'||creditFilterV4==='Applications'&&['Application pending','Under review'].includes(c.status)||creditFilterV4==='Closed'&&(c.status==='Closed'||c.archived)));}
function creditDetailsV4(c){const bal=creditBalanceV4(c),available=creditAvailableV4(c),missing=creditMissingV4(c),link=safeCreditUrlV4(c.sourceUrl),docs=S.intake.filter(x=>(c.intakeIds||[]).includes(x.id));
 const pairs=[['Term starting point',c.termsBasis||'Not confirmed'],['Requested limit',c.requestedLimit==null?'Not provided':money(c.requestedLimit)],['Approved limit',creditLimitV4(c)],['Available credit',available.label+' — '+available.note],['Late fees / interest',c.lateFee||'Not provided'],['Guarantee required',c.guarantee||'Not confirmed'],['ACH / credit-check consent',c.achConsent||'Not confirmed'],['Account contact',c.contact||'Not provided'],['Account reference (masked)',c.maskedAccount||'Not provided'],['Last terms review',c.reviewedOn||'Not reviewed'],['Renewal / review due',c.renewalDate||'Not provided'],['Terms / evidence',c.source||'Source needed']];
 return `<div class="credit-detail-v4"><div class="credit-detail-head"><div><h3>${esc(c.name)} · account details</h3><p class="sub">${missing.length?'Missing: '+esc(missing.join(', ')):'Core account fields entered; verify against the agreement.'}</p></div><div class="actions">${creditBtnV4('Edit account & terms','edit',c.id,'btn primary')}${c.linkedLoan?btnV3('Financing schedule →','nav','data-page="financing"'):c.linkedVendor?creditBtnV4('Open vendor invoices →','vendor',c.id):''}</div></div><dl class="credit-details-grid">${pairs.map(([l,v])=>`<div><dt>${esc(l)}</dt><dd>${esc(v)}</dd></div>`).join('')}${c.linkedLoan?`<div><dt>Scheduled weekly withdrawal</dt><dd>${money(S.loan.weekly)} · first ${esc(S.loan.first)}</dd></div><div><dt>Contractual repayment tracked</dt><dd>${money(bal)} · not a current payoff quote</dd></div>`:''}</dl><div class="credit-detail-source">${link?`<a class="btn small" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open source agreement ↗</a>`:'No source agreement link entered.'}${docs.length?`<p>Linked application records: ${docs.map(d=>esc(d.filename)).join(', ')}</p>`:''}${c.notes?`<p><b>Notes:</b> ${esc(c.notes)}</p>`:''}<p>No account here grants new borrowing capacity or changes cash, AP, or AR. Terms stay separate from scenario payment dates.</p></div></div>`;
}
const creditQueueViewBeforeV4=creditScreenV3;
creditScreenV3=function(){initCreditV4();const all=S.creditAccountsV4,rows=creditVisibleV4(),apps=S.intake.filter(x=>x.bucket==='Credit apps'),termsCount=all.filter(x=>x.terms&&x.terms!=='Not confirmed').length;
 return title('Credit apps','Existing accounts and terms first. Forms and missing-information reviews below.',`<a class="btn" href="${CREDIT_FOLDER.url}" target="_blank" rel="noopener noreferrer">Open Drive folder ↗</a>`+creditBtnV4('+ Add account','new','','btn primary'))+
 `<section class="panel credit-register-v4" id="credit-register"><div class="panel-head"><div><div class="eyebrow">EXISTING ACCOUNTS & APPLICATIONS</div><h2>Credit register</h2><p class="sub">${all.length} records · ${termsCount} with terms recorded · balances linked to your ledger, not added again</p></div>${creditBtnV4('Export register','export')}</div><div class="toolbar"><input id="credit-search-v4" type="search" class="search" placeholder="Find vendor, lender, terms or status…" value="${esc(creditQueryV4)}" aria-label="Search credit register"><select id="credit-filter-v4" aria-label="Filter credit register">${['All accounts','Needs terms','Terms recorded','Applications','Closed'].map(x=>`<option ${x===creditFilterV4?'selected':''}>${x}</option>`).join('')}</select></div><div class="table-wrap"><table class="credit-table-v4"><thead><tr><th>Vendor / lender</th><th>Account status</th><th>Payment terms</th><th class="money">Approved limit</th><th class="money">Tracked balance</th><th>Available credit</th><th>Details</th></tr></thead><tbody>${rows.map(c=>{const b=creditBalanceV4(c),av=creditAvailableV4(c),termKnown=c.terms&&c.terms!=='Not confirmed',expanded=creditExpandedV4===c.id;return `<tr class="credit-row-v4 ${expanded?'is-open':''}"><td><button class="credit-name-v4" data-credit-v4="expand" data-id="${esc(c.id)}" aria-expanded="${expanded}">${esc(c.name)}</button><span class="mini">${esc(c.type)}</span></td><td><span class="pill ${c.status==='Approved'?'green':c.status==='Closed'||c.status==='Declined'?'neutral':'amber'}">${esc(c.status)}</span></td><td><strong>${esc(c.terms||'Not confirmed')}</strong><span class="mini">${termKnown?c.type==='Term loan'?'Verify agreement / payoff':'Terms shown on record; see source':'Agreement needed'}</span></td><td class="money ${c.approvedLimit==null?'credit-unknown-v4':''}">${esc(creditLimitV4(c))}</td><td class="money">${b===null?'Not linked':money(b)}<span class="mini">${c.linkedLoan?'Scheduled repayment, not payoff':c.linkedVendor?'AP snapshot · verify current balance':'No linked ledger'}</span></td><td><span class="${av.amount!==null?'positive':'credit-unknown-v4'}">${esc(av.label)}</span></td><td>${creditBtnV4(expanded?'Close':'Details','expand',c.id)}${creditBtnV4('Edit','edit',c.id,'text-btn')}</td></tr>${expanded?`<tr class="credit-expanded-v4"><td colspan="7">${creditDetailsV4(c)}</td></tr>`:''}`}).join('')||'<tr><td colspan="7" class="empty">No matching accounts. Change the filter or add an account.</td></tr>'}</tbody></table></div><div class="credit-register-note">Existing vendor relationships are not proof of an approved credit limit. <b>Not provided</b> means unknown—not $0. Source terms are retained; no standard terms are guessed.</div></section>`+
 `<section class="panel section-gap credit-intake-v4"><div class="panel-head"><div><h2>Applications & missing information</h2><p class="sub">${apps.length} application${apps.length===1?'':'s'} · separate from the existing-account register</p></div>${btnV3('+ Choose applications','credit-upload')}</div><div class="dropzone" data-drop="Credit apps" data-burn="upload" data-bucket="Credit apps">Drop a credit application here<span class="mini">Text / CSV field checks · PDF and image review needed · no automatic approval</span></div><div class="table-wrap"><table><thead><tr><th>Application</th><th>Review status</th><th>Linked account</th><th>Actions</th></tr></thead><tbody>${apps.map(x=>{const c=all.find(c=>(c.intakeIds||[]).includes(x.id));return `<tr><td>${esc(x.filename)}</td><td>${esc(x.status)}</td><td>${c?esc(c.name):'Not linked'}</td><td><div class="actions">${btnV3('Review missing fields','credit-review',`data-id="${esc(x.id)}"`,'btn small')}${creditBtnV4(c?'Change account link':'Link / add account','link',x.id)}</div></td></tr>`}).join('')||'<tr><td colspan="4" class="empty">No applications in the review queue. Add a form or open the Drive folder.</td></tr>'}</tbody></table></div></section>`+
 `<details class="panel section-gap credit-profile-v4"><summary>Reusable company profile & information still needed</summary><div class="panel-body prose"><p><b>Company:</b> Legal applicant name, DBA, entity type, formation date, business and billing addresses, company phone, and application contact.</p><p><b>Account:</b> Vendor, requested and approved limits (separately), payment terms and starting point, renewal dates, late charges, approved account contact, and agreement link.</p><p><b>Supporting evidence:</b> Authorized trade/bank-reference contacts, W-9, insurance certificate and financial records only where the actual form requires them.</p><p><b>Approvals:</b> Signatures, guarantees, credit checks, ACH consent and final submission require review. Do not enter SSNs, bank logins or full account numbers here.</p><a class="btn small" href="https://docs.google.com/document/d/1ADTS_ET212Fmx66O6rWf0BfDh8kUm575E8MC7cPkwjw/edit" target="_blank" rel="noopener noreferrer">Open company profile ↗</a></div></details>`+
 `<div class="notice"><b>Local register, not a live lender connection.</b> The Drive Credit apps folder was checked October 14, 2026; it contained the profile document and Review results folder, but no application forms. Hourly Drive reviews are separate from this browser. This page does not scan Drive or automatically import their results. Application review does not authorize credit or payments.</div>`;
};
function creditInputV4(name,label,value='',type='text',options=null,full=false){return `<div class="field ${full?'full':''}"><label for="cr-${name}">${esc(label)}</label>${options?`<select id="cr-${name}" name="${name}">${options.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x||'Not linked')}</option>`).join('')}</select>`:`<input id="cr-${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${name==='name'?'required':''} ${type==='number'?'min="0" step="0.01"':''} maxlength="${name==='maskedAccount'?4:1000}">`}</div>`;}
function openCreditV4(id=null,linkIntake=null){initCreditV4();creditEditIdV4=id;creditLinkIntakeV4=linkIntake;const x=S.creditAccountsV4.find(x=>x.id===id)||{name:'',type:'Trade account',status:'Application pending',terms:'Not confirmed',termsBasis:'Not confirmed',requestedLimit:null,approvedLimit:null,limitConfirmed:false,utilizationVerified:false,guarantee:'Not confirmed',achConsent:'Not confirmed'};
 const f=creditInputV4;let body=f('name','Vendor / lender',x.name)+f('type','Account type',x.type,'text',CREDIT_TYPES_V4)+f('status','Account status',x.status,'text',CREDIT_STATUS_V4)+f('linkedVendor','Link to AP vendor',x.linkedVendor||'','text',['',...new Set(S.ap.map(x=>x.vendor))])+f('terms','Payment terms as stated',x.terms)+f('termsBasis','Term starting point',x.termsBasis)+f('requestedLimit','Requested limit ($) — blank if unknown',x.requestedLimit==null?'':x.requestedLimit/100,'number')+f('approvedLimit','Approved limit ($) — blank if unknown',x.approvedLimit==null?'':x.approvedLimit/100,'number')+`<label class="checklabel full"><input name="limitConfirmed" type="checkbox" ${x.limitConfirmed?'checked':''}>Approved limit verified against the lender/vendor’s written approval</label><label class="checklabel full"><input name="utilizationVerified" type="checkbox" ${x.utilizationVerified?'checked':''}>Linked utilization reconciled (including pending purchases or holds)</label>`+f('lateFee','Late fees / interest as stated',x.lateFee||'Not provided')+f('guarantee','Guarantee requirement',x.guarantee||'Not confirmed','text',['Not confirmed','Required','Not required'])+f('achConsent','ACH / credit-check consent status',x.achConsent||'Not confirmed')+f('contact','Vendor account contact',x.contact)+f('maskedAccount','Account reference — last 4 only',x.maskedAccount)+f('reviewedOn','Terms last reviewed',x.reviewedOn,'date')+f('renewalDate','Renewal / review date',x.renewalDate,'date')+f('sourceUrl','Agreement / document URL (HTTPS)',x.sourceUrl,'url',null,true)+f('source','Evidence and source notes',x.source,'text',null,true)+f('notes','Account notes / missing information',x.notes,'text',null,true)+`<p class="prose full">This stores an account record only. It does not create cash, change AP, change invoice terms, sign a guarantee or authorize a credit check. A term loan is not a revolving credit limit.</p>`;
 document.getElementById('credit-dialog-title').textContent=id?'Edit '+x.name:'Add a credit account';document.getElementById('credit-dialog-body').innerHTML=`<div class="form-grid">${body}</div>`;document.getElementById('credit-dialog-error').textContent='';document.getElementById('credit-editor-v4').showModal();}
function closeCreditV4(){document.getElementById('credit-editor-v4').close();}
function creditNumberV4(v){if(v.trim()==='')return null;const n=Number(v);if(!Number.isFinite(n)||n<0||n>1e10)throw Error('Enter a valid nonnegative limit or leave it blank.');return Math.round(n*100);}
function saveCreditV4(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),old=S.creditAccountsV4.find(c=>c.id===creditEditIdV4)||{};try{if(!f.name.trim())throw Error('Enter a vendor or lender.');if(S.creditAccountsV4.some(c=>c.id!==creditEditIdV4&&c.name.toLowerCase()===f.name.trim().toLowerCase()))throw Error('This account already exists. Edit or link the existing account.');if(!CREDIT_TYPES_V4.includes(f.type)||!CREDIT_STATUS_V4.includes(f.status))throw Error('Select a valid type and status.');if(f.sourceUrl&&!safeCreditUrlV4(f.sourceUrl))throw Error('Use an HTTPS document URL.');for(const k of ['reviewedOn','renewalDate'])if(f[k]&&!dateOK(f[k]))throw Error('Use valid review dates.');const approved=creditNumberV4(f.approvedLimit),requested=creditNumberV4(f.requestedLimit);if(f.limitConfirmed&&(approved===null||f.status!=='Approved'))throw Error('To confirm a limit, enter an approved amount and choose Approved status.');if(f.type==='Term loan'&&(approved!==null||f.limitConfirmed))throw Error('Do not enter loan principal as a revolving approved limit. Leave the limit blank for a term loan.');
 const c={...old,id:old.id||'credit-account-'+Date.now(),name:f.name.trim(),type:f.type,status:f.status,linkedVendor:f.type==='Term loan'?'':f.linkedVendor,terms:f.terms.trim()||'Not confirmed',termsBasis:f.termsBasis.trim()||'Not confirmed',requestedLimit:requested,approvedLimit:approved,limitConfirmed:!!f.limitConfirmed,utilizationVerified:!!f.utilizationVerified,maskedAccount:f.maskedAccount.trim(),lateFee:f.lateFee.trim()||'Not provided',guarantee:f.guarantee,achConsent:f.achConsent.trim()||'Not confirmed',contact:f.contact.trim(),reviewedOn:f.reviewedOn,renewalDate:f.renewalDate,sourceUrl:f.sourceUrl.trim(),source:f.source.trim(),notes:f.notes.trim(),intakeIds:old.intakeIds||[],archived:f.status==='Closed'};
 if(c.maskedAccount.length>4)throw Error('Use only the last four account characters.');
 if(creditLinkIntakeV4){for(const other of S.creditAccountsV4)other.intakeIds=(other.intakeIds||[]).filter(i=>i!==creditLinkIntakeV4);c.intakeIds=[...new Set([...c.intakeIds,creditLinkIntakeV4])];}
 if(old.id)S.creditAccountsV4[S.creditAccountsV4.findIndex(x=>x.id===old.id)]=c;else S.creditAccountsV4.push(c);creditExpandedV4=c.id;save('Updated credit account '+c.name+' (no cash or ledger posting)');closeCreditV4();toast('Account saved. Cash and invoice balances are unchanged.');
 }catch(err){document.getElementById('credit-dialog-error').textContent=err.message;}}
function linkCreditV4(id){const x=S.intake.find(x=>x.id===id);if(!x)return;creditLinkIntakeV4=id;const c=S.creditAccountsV4.find(c=>(c.intakeIds||[]).includes(id));document.getElementById('credit-link-name').textContent=x.filename;document.getElementById('credit-link-select').innerHTML='<option value="">Add a new account record</option>'+S.creditAccountsV4.map(x=>`<option value="${esc(x.id)}" ${x.id===c?.id?'selected':''}>${esc(x.name)}</option>`).join('');document.getElementById('credit-link-v4').showModal();}
function exportCreditV4(){const rows=[['Vendor / lender','Type','Status','Terms','Term starting point','Requested limit USD','Approved limit USD','Limit verified','Tracked balance USD','Balance basis','Available credit USD','Utilization verified','Fees / interest','Guarantee','Consent status','Contact','Masked reference','Reviewed on','Renewal due','Evidence','Document URL','Notes']];for(const c of S.creditAccountsV4){const b=creditBalanceV4(c),av=creditAvailableV4(c);rows.push([c.name,c.type,c.status,c.terms,c.termsBasis,c.requestedLimit==null?'':c.requestedLimit/100,c.approvedLimit==null?'':c.approvedLimit/100,c.limitConfirmed?'Yes':'No',b===null?'':b/100,c.linkedLoan?'Scheduled repayment, not payoff':'AP snapshot',av.amount===null?'':av.amount/100,c.utilizationVerified?'Yes':'No',c.lateFee,c.guarantee,c.achConsent,c.contact,c.maskedAccount,c.reviewedOn,c.renewalDate,c.source,c.sourceUrl,c.notes]);}download('OverSite_credit_register.csv',toCSVV3(rows),'text/csv');}
document.body.insertAdjacentHTML('beforeend',`<dialog id="credit-editor-v4"><form id="credit-form-v4"><div class="dialog-head"><h2 id="credit-dialog-title">Credit account</h2><button type="button" class="icon-btn" data-credit-v4="close" aria-label="Close account editor">×</button></div><div id="credit-dialog-body"></div><p id="credit-dialog-error" role="alert"></p><div class="dialog-foot"><button type="button" class="btn" data-credit-v4="close">Cancel</button><button type="submit" class="btn primary">Save account</button></div></form></dialog><dialog id="credit-link-v4"><form id="credit-link-form-v4"><div class="dialog-head"><h2>Link application to an account</h2></div><div class="panel-body" style="padding-top:18px"><p id="credit-link-name"></p><label class="field">Existing account<select id="credit-link-select"></select></label><p class="prose">Linking stores the relationship only. It does not approve terms or change credit limits.</p></div><div class="dialog-foot"><button type="button" class="btn" data-credit-v4="close-link">Cancel</button><button type="submit" class="btn primary">Continue</button></div></form></dialog>`);
document.getElementById('credit-form-v4').addEventListener('submit',saveCreditV4);
document.getElementById('credit-link-form-v4').addEventListener('submit',e=>{e.preventDefault();const id=document.getElementById('credit-link-select').value,application=creditLinkIntakeV4;document.getElementById('credit-link-v4').close();if(!id)return openCreditV4(null,application);for(const c of S.creditAccountsV4)c.intakeIds=(c.intakeIds||[]).filter(x=>x!==application);S.creditAccountsV4.find(c=>c.id===id).intakeIds.push(application);creditExpandedV4=id;save('Linked application to credit account (no approval or cash effect)');});
document.addEventListener('click',e=>{const t=e.target.closest('[data-credit-v4]');if(!t)return;const id=t.dataset.id;switch(t.dataset.creditV4){case 'new':openCreditV4();break;case 'edit':openCreditV4(id);break;case 'close':closeCreditV4();break;case 'expand':creditExpandedV4=creditExpandedV4===id?null:id;render();break;case 'export':exportCreditV4();break;case 'vendor':{const c=S.creditAccountsV4.find(c=>c.id===id);page='ap';q=c?.linkedVendor||'';render();break;}case 'link':linkCreditV4(id);break;case 'close-link':document.getElementById('credit-link-v4').close();break;}});
document.addEventListener('input',e=>{if(e.target.id==='credit-search-v4'){const pos=e.target.selectionStart;creditQueryV4=e.target.value;render();const el=document.getElementById('credit-search-v4');el.focus();el.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='credit-filter-v4'){creditFilterV4=e.target.value;render();}});
window.OverSite.version=4;window.OverSite.creditAccounts=()=>deep(S.creditAccountsV4);window.OverSite.creditAvailable=id=>creditAvailableV4(S.creditAccountsV4.find(c=>c.id===id));
