// re-render the global runway cards. Keep all v3 planning edits and storage keys.
const brandV4=document.querySelector('.brand');brandV4.href='#forecast';brandV4.dataset.v3='nav';brandV4.dataset.page='forecast';
const oldRenderCreditV4=render;render=function(){oldRenderCreditV4();document.body.dataset.page=page;document.querySelector('.preview-band span').innerHTML='<b>Strategy workspace v4</b> · Shared Google ledger. Plans do not send payments.';};

